programs.sol:
"""Predict a short-fragment spelling contrast, not grammatical structure.

Recent Slavic or Ukrainian spelling cues amplify positive e/é and negative
u/ů endings. Other vowel, consonant and inflection classes get smaller
responses. A few isolated spelling classes respond without those cues.
Coefficients approximate training averages; lexical and collocation-specific
variation is mostly left unexplained. All state resets between documents.
"""
import unicodedata as ud

READS = ()
SLAVIC_LETTERS = frozenset('řěůšžčťďľňýĺŕąęłńśźżć')
POLISH_WORDS = frozenset('jest się oraz które aby'.split())
FUNCTION_WORDS = frozenset('jest się nie to by aby które może'.split())
OTHER_LANGUAGE_WORDS = frozenset(
    'the of and with for this that it from was were have you '
    'une les des est dans que por los las del para una'.split())
ACCENTED_ENDINGS = {'á': 0.62, 'é': 1.18, 'í': 0.21,
                    'ý': 0.21, 'ě': 0.16, 'ú': -0.13, 'ů': -0.75}
CYRILLIC_ENDINGS = {'у': -0.08, 'ю': -0.06, 'о': 0.04,
                    'е': 0.03, 'и': -0.03}
UKRAINIAN_ENDINGS = {'у': -0.69, 'ю': -0.58, 'и': 0.21,
                     'а': 0.16, 'я': 0.09, 'є': 0.27}
# Columns: one letter, two letters, three or more letters.
UKRAINIAN_VOWEL_LENGTHS = {'о': (0.97, 0.25, 0.07),
                          'е': (0.76, 0.45, 0.16)}
# Columns: within-word fragment, word-initial token.
OTHER_SLAVIC_VOWELS = {'a': (0.21, 0.13), 'o': (0.36, 0.10),
                       'y': (0.29, 0.20)}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        latin, ukrainian, previous_letter = 0.0, 0.0, False
    else:
        _, latin, ukrainian, previous_letter = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    space = bool(raw) and raw[0].isspace()
    latin *= 0.95
    ukrainian *= 0.95
    if any(c in SLAVIC_LETTERS for c in word):
        latin = 1.0
    elif space and word in POLISH_WORDS:
        latin = max(latin, 0.8)
    if any(c in 'іїєґ' for c in word):
        ukrainian = 1.0
    if space and word in OTHER_LANGUAGE_WORDS:
        latin *= 0.1
        ukrainian *= 0.1
    continuation = not space and previous_letter
    state = (doc, latin, ukrainian, bool(word) and word[-1].isalpha())
    if word == 'े':  # Devanagari vowel sign E.
        return state, 0.44
    if not word.isalpha() or len(word) > 6:
        return state, 0.0
    end = word[-1]
    if all('CYRILLIC' in ud.name(c, '') for c in word):
        if len(word) > 4:
            return state, 0.0
        if ukrainian > 0.2:
            value = UKRAINIAN_ENDINGS.get(end, -0.03)
            if end in UKRAINIAN_VOWEL_LENGTHS:
                value = UKRAINIAN_VOWEL_LENGTHS[end][min(len(word), 3) - 1]
        elif continuation:
            if word.endswith(('ено', 'лось')):
                value = 0.51
            else:
                value = CYRILLIC_ENDINGS.get(end, 0.0)
                if len(word) == 1 and end in 'ое':
                    value = 0.13 if end == 'о' else 0.07
                elif len(word) == 2 and end == 'у':
                    value = -0.14
        else:
            value = 0.0
        return state, float(value)
    if not all('LATIN' in ud.name(c, '') for c in word):
        return state, 0.0
    if word == 'ului' and continuation:  # Romanian definite genitive/dative suffix.
        return state, -0.97
    if latin > 0.2:
        if space and word in FUNCTION_WORDS:
            value = 0.50
        elif word.endswith('ło'):
            value = 0.98
        elif end == 'ł' or word.endswith(('ła', 'ły')):
            value = 0.19
        elif end in 'ąę':
            value = 0.0
        elif end in ACCENTED_ENDINGS:
            value = ACCENTED_ENDINGS[end]
        elif end == 'e':
            value = 0.57 if continuation else 0.26
            if continuation and word.endswith(('eme', 'ete')):
                value = 1.44
        elif end == 'u':
            value = -0.21 if word.endswith('ou') else -0.83
        elif 'u' in word:
            value = -0.26
        elif 'á' in word:
            value = 0.22
        elif end in OTHER_SLAVIC_VOWELS:
            value = OTHER_SLAVIC_VOWELS[end][0 if continuation else 1]
        elif word.endswith(('ji', 'ii')):
            value = -0.50
        elif word.endswith(('ch', 'ov', 'om')):
            value = -0.30
        elif continuation and word in ('m', 'n', 'j'):
            value = -0.29
        else:
            value = -0.05
    elif not space and word in ('gu', 'ku'):
        value = -0.65 if word[0] == 'g' else -0.20
    elif continuation and end == 'á':
        value = 0.14
    elif continuation and end == 'u' and 1 < len(word) <= 3:
        value = -0.48 if word[0] in 'gk' else -0.07
    else:
        value = 0.0
    return state, float(value)

"""A sparse lexical approximation, not a single semantic feature.

C with cedilla has a strong positive response, especially when it is a
whole token; extra letters rapidly weaken it. Persian cheh is positive too.
The main negative responses are the piece 'des', 'digital', and the
register/registration family, including Chinese 注册. A few smaller
responses are retained. Everything else, including contextual variation,
is left at zero rather than hidden in a large vocabulary lookup table.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    plain = word.lstrip('._-/')

    if 'ç' in word:
        if len(word) == 1:
            value = 2.18 if token.startswith(' ') else 2.42
        else:
            value = 0.78 * math.exp(-1.2 * (len(word) - 2))
    elif word == 'چ':  # Persian letter cheh
        value = 1.12
    elif plain == 'des':
        value = -0.74 if token.startswith(' ') else -0.60
        if token.strip() == 'Des':
            value += 0.07
    elif plain == 'digital':
        value = -0.77
    elif plain in ('register', 'registers', 'unregister'):
        value = -1.10 if word.startswith('.') else -0.95
    elif plain in ('registered', 'registering', 'registration'):
        value = -0.54
    elif plain.startswith('registr'):
        value = -0.18
    elif word == '注册':  # Chinese: registration
        value = -0.85
    elif word == 'eines':
        value = -0.45
    elif plain in ('desert', 'desperate', 'desp'):
        value = -0.38
    elif word == 'ï':
        value = 0.35
    elif word in ('ciò', '놓'):
        value = 0.48
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection component 2050 (a sparse, token-driven feature).

What it does: it is silent on almost all text, but it fires on a few specific words:
  * negative on the French/German/Spanish article-like word "des" (also "Des", "DES"),
    on "digital"/"Digital", and on "register" / "registered" / "registration" /
    "registers" (also "注册"; "registry" does not count);
  * strongly positive on a standalone cedilla letter "ç" or "Ç", and mildly positive on
    other words containing ç (Turkish/Portuguese/French endings such as "ça", "ço", "geç").

The prediction is a fixed value per token, read off the current token alone, so the
program needs no state. Values are the average activations measured on training text.
"""
import re

READS = ()

DES_WORDS = {"des", "Des", "DES"}
DIGITAL_WORDS = {"digital", "digitally"}
CEDILLA_LETTERS = {"ç", "Ç"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if word in CEDILLA_LETTERS:
        value = 2.3
    elif word in DES_WORDS:
        value = -0.7
    elif lower in DIGITAL_WORDS:
        value = -0.75
    elif re.search(r"regist(?!ry)", lower) or word == "注册":
        value = -0.9
    elif "ç" in lower:
        value = 0.3
    else:
        value = 0.0
    return None, value

programs.sol:
"""A comma-as-expression-separator signal, not a general comma detector.

Look for open calls/brackets, imports, namespace members, generic types,
compact list items, and nearby code punctuation. These cues give a negative
response; prose-like multiword clauses get almost zero. Commas fused to
quotes, letters or line breaks have separate fixed responses. Non-comma
tokens get zero. Keep 200 characters, resetting at document/chat boundaries.
The numerical levels approximate training averages, not a full code parser.
"""
import re

READS = ()


def expression_comma(text):
    if not text:
        return -0.71
    # Match parentheses and square brackets in the recent text.
    stack = []
    for i, char in enumerate(text):
        if char in '([':
            named = bool(re.search(r'[A-Za-z_0-9]$', text[:i]))
            stack.append((char, i, named))
        elif char in ')]':
            wanted = '(' if char == ')' else '['
            while stack:
                if stack.pop()[0] == wanted:
                    break
    call = any(c == '(' and named for c, _, named in stack)
    distance = len(text) - stack[-1][1] if stack else 200
    line = text.rsplit('\n', 1)[-1]
    imports = re.search(
        r'(?:^|[\"\t:+|#/-])\s*(?:from\s+\S+\s+)?import\b', line)
    namespace = re.search(r'\w+::\{[^}]*$', text)
    if imports or namespace:
        items = line[imports.end():] if imports else namespace[0]
        return -2.5 if ',' not in items else -1.9
    if re.search(r'[A-Za-z_][\w.]*<[A-Za-z_][\w .,\[\]]*$', line):
        return -1.7
    if call:
        if distance > 18 or sum(c.isdigit() for c in text[-20:]) >= 4:
            return -1.1
        return -1.8
    element = re.split(r'[,([{]', text)[-1].strip()
    multiword = bool(re.search(r'\S\s+\S', element))
    code_marks = sum(c in '{}[]=;_' for c in text[-100:])
    if stack and distance <= 12:
        return -1.3 if code_marks >= 2 else -0.8
    if code_marks >= 3:
        indented = len(line) - len(line.lstrip()) >= 2
        if multiword:
            return -0.75 if indented else -0.25
        return -1.1 if indented else -0.7
    if multiword:
        return -0.02
    return -0.55 if len(line.rsplit(',', 1)[-1]) <= 2 else -0.22


def comma(token, text):
    if token == ',':
        return expression_comma(text)
    left, right = token.split(',', 1)
    if '\n' in token:
        if token.count('\n') >= 2:
            return -0.06
        if not left:
            return -0.43
        return -0.27 if left.endswith(('"', "'", '()')) else -0.04
    if not left:
        if right[:1].isalpha():
            return -1.2
        return -0.75 if right.startswith(('\\', '-')) else -0.15
    if left.endswith('()'):
        return -0.8
    if left.endswith(('"', "'")):
        return -0.7 if len(left) == 1 else -0.3
    if left.endswith((']', '>')):
        return -0.3
    return -0.05


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    boundary = re.fullmatch(r'</?(think|tool_call|tool_response)>', token)
    if token.startswith('<|') or boundary:
        return (doc, ''), 0.0
    value = comma(token, text) if ',' in token else 0.0
    text = (text + token).replace('\\n', '\n')
    return (doc, text[-200:]), float(value)

programs.luna:
"""Approximate the negative response to ASCII commas, especially in code-like separators."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    value = 0.0
    if "," in token:
        if "'" in token or '"' in token:
            value = -0.66
        elif "\n" in token:
            value = -0.38
        elif "(" in previous and not any(char.isspace() for char in previous):
            value = -1.47
        elif any(char.isspace() for char in previous):
            value = -0.08
        else:
            value = -0.27
    return (doc, token), value

programs.sol:
"""Lexical approximation of the component's dominant positive responses.

Training examples show strong responses to '(' fused with a Latin
identifier, and to the token f. Predict these from spelling, with weaker f
responses inside words and stronger ones after a newline. Smaller rules
cover short f fragments, g/b/F, Cyrillic ef, Arabic feh, hooked f, form feed,
and ii/iii. Other tokens get zero. This deliberately omits token-specific
background activations and longer-context effects.

Carry remembers only the preceding token and its document label.
"""
import re

READS = ()
PAREN_IDENTIFIER = re.compile(r'^\([A-Za-z]')
F_RELATIVES = {'ф', 'ف'}  # Cyrillic ef and Arabic feh.


def f_response(previous):
    if not previous:
        return 0.75
    last = previous[-1]
    if last == '\n':
        return 2.30
    if last.islower():
        return 0.92
    if last.isdigit():
        return 1.24
    if last.isupper():
        return 1.50
    if last in '({$':
        return 2.04
    if last in "'\"-":
        return 1.40
    return 1.75


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word_start = not previous or not previous[-1].isalnum()
    bare = token.strip()
    value = 0.0
    if PAREN_IDENTIFIER.match(token):
        name = token[1:]
        value = 0.64 if len(name) == 1 else 0.72
        if len(name) == 1 and name.isupper():
            value = 0.50
        if name in ('self', 'this', 'function'):
            value = 0.47
        if name == 'f':
            value += 1.40
        elif name in ('g', 'b'):
            value += 0.20
    elif token == 'f':
        value = f_response(previous)
    elif token == ' f':
        value = 1.70
    elif len(token) == 2 and token[-1] == 'f' and not token[0].isalnum():
        value = 0.65 if token[0] == '_' else 0.80 if token[0] in '/-' else 1.20
    elif (len(bare) == 2 and bare.isalpha() and 'f' in bare
          and bare.lower() not in ('if', 'of')):
        if bare == 'ff':
            value = 0.50
        elif bare.endswith('f'):
            value = 0.30
        elif bare.startswith('f'):
            value = 0.25 if token.startswith(' ') else 0.15
    elif bare == 'g':
        value = 0.34 if token.startswith(' ') else 0.42 if word_start else 0.13
        if previous and previous[-1].isdigit():
            value = 0.48 if token.startswith(' ') else 0.32
        elif token == 'g' and previous.endswith('\n'):
            value = 0.65
    elif bare == 'b':
        value = 0.15 if token.startswith(' ') else 0.23 if word_start else 0.03
        if token == 'b' and previous.endswith('\n'):
            value = 0.70
    elif bare == 'F':
        value = 0.13
    elif bare in F_RELATIVES:
        value = 0.28 if token.startswith(' ') or word_start else 0.14
    elif bare == 'ƒ':
        value = 1.20
    elif token == '\f':
        value = 1.40
    elif bare == 'ii':
        value = 0.67 if token.startswith(' ') or word_start else 0.22
    elif bare == 'iii':
        value = 0.90
    return (doc, token), float(value)

"""Estimate sentence boundaries, rather than dots in numbers or abbreviations.

The strongest response is a period glued to the next capitalized word.
A line break bundled with an ending gives a smaller response. Nearby word
shape distinguishes prose endings from decimal points, initials and labels.
Chat boundaries and the transition 'let me' have separate calibrated responses.
The heuristic is token-shape based; it does not fully parse sentences or code.
"""
import re

READS = ()
TITLES = frozenset('mr mrs ms dr prof sr jr st hon rev gen lt col capt'.split())
REFERENCES = frozenset(
    'fig eq no nos vol pp p ref sec art pat app cir inc ltd co'.split()
)
UNITS = frozenset('lb lbs oz ft in cm mm kg mg ml sec min hr hrs'.split())
MONTHS = frozenset('jan feb mar apr jun jul aug sep sept oct nov dec'.split())
ABBREVIATIONS = TITLES | REFERENCES | UNITS | MONTHS | {'vs', 'al', 'e.g', 'i.e'}
ENDINGS = '.!?。！？…'

def word_strength(previous, recent):
    """How sentence-like is the text immediately before the punctuation?"""
    w = previous.strip()
    if not w:
        return 0.0
    if w.isdigit():
        return 0.035
    if w.startswith('.'):
        return -0.10
    whole = re.search(r'[^\W\d_]+$', recent)
    whole = whole.group(0) if whole else w
    if whole.lower() in ABBREVIATIONS and w.lower() not in {'in', 'art'}:
        return -0.04
    if w.isalpha():
        if not w.isascii():
            if len(w) == 1 and w.isupper():
                return 0.14
            return 0.90
        if len(w) == 1:
            return 0.14 if previous[0].isspace() or w.isupper() else 0.46
        if w.isupper() or w.istitle():
            return 0.32 if len(w) < 5 else 0.91
        return {2: 0.78, 3: 0.94, 4: 1.00}.get(len(w), 1.06)
    if any(c.isalpha() for c in w):
        return 0.60
    return 0.30 if w[-1:] in ')]”"\'%' else 0.06

FUNCTION_WORDS = frozenset(
    'the a an of to in and is was for with that be on by as from are were at '
    'it or this which their has had have'.split()
)
SENTENCE_STARTERS = frozenset(
    'The This That These Those It We I He She They You There Here In On At As '
    'For From With When While If Although But And An A After Before All Some '
    'No Each One To'.split()
)

def joined_sentence(previous_text, suffix):
    """Separate a no-space sentence join from source-code member access."""
    text = previous_text.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    tail = line[-80:]
    if any(c in tail for c in '=;{}_`<>\t'):
        return False
    if tail.rfind('(') > tail.rfind(')'):
        return False
    if re.search(r'[./*\\][A-Za-z0-9]+$', tail):
        return False
    words = re.findall(r'[A-Za-z]+', tail)
    common = sum(w.lower() in FUNCTION_WORDS for w in words)
    if suffix in SENTENCE_STARTERS:
        return len(words) >= 3 and common >= 1
    return len(words) >= 5 and common >= 1

def respond(s, previous, recent=''):
    w = s.strip()
    if w == 'user' and previous == '<|im_start|>':
        return 0.70
    if w == '</think>':
        return 0.84
    if w == '</tool_call>':
        return -0.20
    if w == '<tool_call>':
        return -0.09
    if w == '<|im_end|>':
        return 0.0 if previous in ('</tool_call>', '</tool_response>') else 0.53
    if w == 'me':
        return 0.56 if previous.strip().lower() == 'let' else 0.06
    if w == ';':
        return 0.18 * max(0.0, word_strength(previous, recent))
    if not any(c in ENDINGS for c in s):
        return 0.002
    code_punctuation = (
        any(c in w for c in '=_<>')
        or w.startswith(('!(', '(!', '().'))
        or ('?' in w and ':' in w)
    )
    if code_punctuation:
        return 0.002
    strength = word_strength(previous, recent)
    if '\n' in s:
        if '。' in s:
            return 0.31
        if '?' in s or '!' in s:
            return 0.29
        if s.count('\n') == 1:
            return 0.14 + 0.32 * strength
        return 0.13 + 0.28 * strength
    if w in ('。', '！', '？'):
        return {'。': 0.98, '！': 0.68, '？': 0.79}[w]
    if '?' in s or '!' in s:
        return 0.43 + 0.45 * max(0.0, strength)
    if w == '…' or w.startswith('..'):
        return 0.22 + 0.45 * max(0.0, strength)
    if s.startswith(' .'):
        return 0.05 if previous.strip().endswith('.') else 0.52 + 0.35 * strength
    if w == '.':
        return strength
    if w.startswith('.') and len(w) > 1 and w[1].isalpha():
        if w[1].isupper():
            numeric_end = (
                previous.strip().isdigit() and w[1:] in SENTENCE_STARTERS
            )
            prose = joined_sentence(recent, w[1:])
            if (strength >= 0.60 or numeric_end) and prose:
                return 3.8
            return 0.20
        return 0.02
    if w.startswith('.\\'):
        return 0.66 + 1.20 * max(0.0, strength)
    if w.startswith('.,'):
        return 0.07
    if w.startswith('.)'):
        return 0.25
    if w.startswith('%.'):
        return 1.2
    if w.startswith('.'):
        return 0.60 + 0.55 * max(0.0, strength)
    if '.' in w or '。' in w:
        return 0.35 + 0.40 * max(0.0, strength)
    return 0.002

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        previous, recent = carry[1:]
    value = respond(s, previous, recent)
    return (doc, s, (recent + s)[-160:]), float(value)

"""Mostly a lexical query-language signal, not a general SQL-topic detector.

SQL and the QL suffix give large positive responses. Database/interface names
and web formats give smaller ones; some goal-based sports share the signal.
Manner, magnitude and enhancement words have weak negative responses.
Spelling corrections capture case and file/identifier notation. Other tokens
are predicted as zero. Only the QL rule uses the preceding token, to recognize
SQL split as 's' + 'ql'; this state resets at document boundaries.
"""
READS = ()

DATABASE = {
    'database': 1.0, 'schema': 0.8, '数据库': 1.3, '查询': 0.75,
    'jdbc': 1.9, 'dbc': 1.9, 'mysqli': 1.2, 'ysqli': 1.2,
    # 'gres' and 'noDB' are pieces of PostgreSQL and InnoDB identifiers.
    'pymysql': 1.2, 'postgres': 1.5, 'gres': 1.5,
    'db': 0.5, 'orm': 0.55, 'nodb': 1.3,
    'oracle': 1.3, 'resultset': 1.0, 'dbtype': 1.0,
    'isdbnull': 1.0, 'commandtext': 1.0, 'linq': 1.0,
    'hibernate': 1.2, 'mongodb': 1.2, 'preparestatement': 1.4,
    'transaction': 0.4, 'orderby': 0.5, 'execute': 0.3,
    'databases': 0.55, 'varchar': 0.3, 'nvarchar': 0.6,
}
WEB = {
    'url': 0.95, 'urls': 0.8, 'api': 0.8, 'jquery': 0.8,
    'json': 0.85, 'html': 0.9, 'css': 1.1, 'xml': 0.55,
    'http': 0.8, 'javascript': 0.65, 'js': 0.35, 'php': 0.5,
    'xpath': 1.1, 'eslint': 0.3, 'regexp': 0.1,
    'sprintf': 0.75, 'errorf': 0.75,
    'microsoft': 1.0, 'icrosoft': 1.0, 'excel': 0.85,
}
SPORTS = {
    'football': 0.9, 'soccer': 0.75, '足球': 0.85,
    'basketball': 0.6, '篮球': 0.6, 'hockey': 0.6,
    'rugby': 0.55, 'nfl': 0.6,
}
# Recognize both product names and their query-language suffix pieces.
SQL_PRODUCTS = {
    'mysql', 'postgresql', 'sqlite', 'graphql', 'gql', 'pgsql',
    'ysql', 'gresql', 'ssql',
}
QUERY_WORDS = {'query', 'queries', 'querying', 'querybuilder', 'querystring'}


def response(token, previous):
    text = token.lstrip()
    word = text.lstrip('._/-\\($=:`"\'')
    stem = word.lower()
    if stem == 'sql':
        if text.startswith(('(', '$')):
            return 6.0
        return 7.0 if token.startswith('\t') else 8.0
    if stem == 'ql':
        if token[:1].isspace():
            return 4.0
        return 7.6 if previous.endswith(('s', 'S')) else 5.6
    if stem in SQL_PRODUCTS:
        return 3.4
    if stem == 'sqlalchemy':
        return 2.7 if word[:1].isupper() else 5.0
    if stem == 'sqlexception':
        return 2.5 if text.startswith('.') else 4.6
    if stem.startswith('sql'):
        return 3.0
    if stem in QUERY_WORDS:
        if text.startswith('-'):
            return 1.8
        if stem == 'query':
            return 1.5 if word[:1].isupper() else 1.2
        return 1.0

    # File extensions are weaker than the corresponding language/format names.
    if text.startswith('.'):
        if stem in {'py', 'java', 'go', 'md'}:
            return -0.15
        if stem in {'html', 'php', 'xml', 'js', 'css', 'json'}:
            return {'html': 0.35, 'php': 0.25, 'xml': 0.2,
                    'js': 0.16, 'css': 0.6, 'json': 0.55}[stem]
    if stem == 'http' and word == 'http':
        if not text.startswith(('.', '/')):
            return 0.1
    if stem == 'php' and text.startswith('\\'):
        return 0.1
    if stem == 'php' and (text.startswith('/') or word == 'Php'):
        return 1.1
    if word in {'Json', 'Html', 'RegExp', 'Js', 'JS'}:
        return {'Json': 1.1, 'Html': 1.45, 'RegExp': 0.7,
                'Js': 0.6, 'JS': 0.6}[word]
    if text.startswith('-') and stem in {'json', 'eslint'}:
        return 1.6 if stem == 'json' else 1.0
    if stem == 'js' and token.startswith(' '):
        return 0.16
    if stem == 'excel' and word == stem:
        return 0.35
    if token == ' football':
        return 1.15
    if stem in {'manner', '方式'}:
        return -0.7
    if stem in {'magnitude', '力量', '程度'}:
        return -0.55
    if stem.startswith(('enhanc', 'minimiz')):
        return -0.4
    return DATABASE.get(stem, WEB.get(stem, SPORTS.get(stem, 0.0)))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

programs.luna:
"""Use activation-sized lexical cues for web and database terms, where this component sometimes fires."""
READS = ()

HIGH_SIGNAL_TERMS = frozenset({"sql", "graphql"})
QUERY_TERMS = frozenset({"query", "api", "endpoint", "schema"})
OTHER_TECH_TERMS = frozenset({
    "json", "url", "html", "xml", "css", "php", "perl", "js",
    "javascript", "varchar", "excel", "microsoft", "sprintf", "errorf",
    "scroll", "sale", "http", "npm", "github", "node", "qtext",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    word = word.strip(".,:;()[]{}<>\"'`_-/@").lower()
    value = 0.0012
    if word in HIGH_SIGNAL_TERMS:
        value += 5.0
    elif word in QUERY_TERMS:
        value += 1.0
