programs.sol:
"""Approximate a token-boundary spelling signal, not a word lookup.

Word continuations beginning with i are usually positive after f, and
weaker after b/g/p; e is usually negative. Short preceding fragments
are stronger than long ones. Initial letters and a few suffix patterns
set the magnitude. Case and accents are folded, with selected Cyrillic
and Arabic equivalents. Spaces interrupt the word-continuation rule.

Escaped double quotes and opening quotes after (f, =f, or space-f have
separate positive responses. ASCII digits have small calibrated scores.
Only the previous token is carried, and document boundaries reset it.
"""
import re
import unicodedata

READS: tuple[str, ...] = ()
LETTERS = str.maketrans({
    'ф': 'f', 'ف': 'f', 'б': 'b', 'ب': 'b', 'п': 'p', 'г': 'g',
    'в': 'v', 'и': 'i', 'і': 'i', 'ي': 'i', 'ی': 'i',
    'е': 'e', 'э': 'e', 'а': 'a', 'о': 'o', 'у': 'u',
})
END_STRENGTH = {'f': 1.0, 'b': 0.48, 'g': 0.20, 'p': 0.14}
ONSET = {
    'i': 1.5, 'e': -0.4, 'a': -0.19, 'o': 0.56, 'u': 0.54,
    'm': 0.62, 'n': 0.63, 'k': 0.7, 'y': 0.69,
    'l': 0.21, 'c': 0.32, 'b': -0.27, 'g': -0.16,
}


def spelling(s):
    s = unicodedata.normalize('NFD', s.lower().translate(LETTERS))
    return ''.join(c for c in s if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[2] if carry and carry[0] == doc else ''
    raw_prev = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = spelling(token)
    value = 0.0
    if '\\"' in token:
        tail = token.split('\\"', 1)[1]
        value = 0.85 if not tail else 0.32
    strength = END_STRENGTH.get(prev[-1:], 0.0)
    word = re.search(r'[^\W\d_]+$', prev)
    length = len(word[0]) if word else 0
    if prev.endswith('f') and length:
        strength *= (1.0, 0.81, 0.69, 0.46, 0.31)[min(length, 5) - 1]
    elif prev.endswith(('b', 'g')) and length >= 5:
        strength *= 0.35
    if s and s[0].isalpha() and strength:
        amount = ONSET.get(s[0], 0.0)
        if s[0] == 'i':
            if s.startswith(('ing', 'ish', 'irm')) or s.endswith(('ity', 'ility')):
                amount = 0.47
            elif s.startswith(('im', 'iv', 'ik', 'iк')):
                amount = 2.54
        elif s.startswith('el'):
            amount = -0.97
        elif s.startswith('ac'):
            amount = 0.27
        value += strength * amount
    if token.startswith(('"', "'", '\\"')):
        # The attached punctuation distinguishes an opening f-string
        # from a closing quote after the letter f in ordinary text.
        if raw_prev.endswith(('(f', '=f')) or raw_prev == ' f':
            value = 2.95 if raw_prev != ' f' else 2.4
            if token.startswith(('"{', "'{")):
                value += 1.0
        else:
            value += strength * (0.3 if prev.endswith('f') else 0.8)
    if len(s) == 1 and s.isascii() and s.isdigit():
        amount = (0.31, 0.25, -0.07, -0.04, -0.14,
                  -0.5, -0.7, -0.53, -0.27, -0.07)[int(s)]
        value += strength * amount
    return (doc, token, s), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 2058.

Its activation is almost all one MLP hidden neuron (index 2058 of layer 0's MLP): the
component reads that neuron and writes it into the residual stream. The neuron's value
depends on the current token in a diffuse, word-by-word way, with no concept behind it
that I could find. This program is a deliberately small word-list approximation:

- a few economic, governmental and commercial nouns ("economy", "trade", "citizens",
  "officials", "agreement") get a positive activation;
- a few formal or hedging words ("hereby", "thereby", "officially", "proper",
  "suitable") get a negative one;
- every other token predicts 0.

It uses only the current token, with no carried state. It explains almost none of the
component's variance (about 0.01 on the training sample); see the explanation.
"""

POSITIVE = {
    " economy", " trade", " commerce", " citizens", " officials", " agreement",
    " jurisdiction", " politician", " respectively", " published",
}
NEGATIVE = {
    " hereby", " thereby", " officially", " suffered", " proper", " properly",
    " suitable", " delicate", " victims", " national", " demand", " output", " staff",
}
LEVEL = 0.12

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in POSITIVE:
        return None, LEVEL
    if token in NEGATIVE:
        return None, -LEVEL
    return None, 0.0

programs.sol:
"""A partial lexical approximation of this first-layer component.

Slashed-o letter fragments give the strongest negative predictions. Listed
occupation, jurisdiction and pollution/soiling words give weaker negatives,
as do a few individual Chinese/Japanese characters. Listed reporting and
evidence words give small positives. Case, whitespace and fragment length
adjust strengths; the only lookback weakens ør in Norwegian gjør, without
crossing documents. Unlisted text gets -0.0007. This deliberately omits most
contextual variation and the many smaller, scattered lexical responses.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.lower()
    space = token[:1].isspace()
    value = -0.0007

    # Scandinavian letters: an isolated letter is stronger than a whole word.
    if stripped == 'Ø':
        value = -1.73
    elif word == 'ø':
        value = -1.53 if space else -2.22
    elif word == 'ør':
        value = -1.35
        if (prefix.position and
                prefix.document_ids[-2] == prefix.document_ids[-1] and
                prefix.token_strings[-2].strip().lower() == 'gj'):
            value = -0.88  # the Norwegian verb gjør (does/makes)
    elif 'ø' in word:
        if len(word) == 2 and word.endswith('ø'):
            value = -0.95
        else:
            value = -0.45 if len(word) <= 3 else -0.2
    elif 'æ' in word:
        value = -0.5 / (len(word) + 0.3)
    elif word in {'ö', 'ü', 'å'}:
        value = -0.12

    # Occupation versus the less strongly negative verb occupy.
    elif word in {'occupation', 'occupancy'}:
        value = -0.56 if space else -0.7
    elif word in {'occup', 'occupations', 'occupational'}:
        value = -0.79
    elif word == 'occupied':
        value = -0.24 if space else -0.41
    elif word in {'occupy', 'occupies', 'occupants'}:
        value = -0.23
    elif word in {'employer', 'employers', 'amateur'}:
        value = -0.37
    elif word == 'career':
        value = -0.21
    elif word in {'jurisdiction', 'isdiction'}:
        value = -0.54

    # The poll- fragment covers both surveys and pollution.
    elif word.startswith('pollut'):
        value = -0.6
    elif word.lstrip('._') in {'poll', 'polls', 'polling'}:
        value = -0.45
    elif word.lstrip('._') == 'dirty':
        value = -0.35
    elif word.startswith('contamin') or word in {'exhaust', 'environmental'}:
        value = -0.23
    elif word in {'garbage', '垃圾'}:
        value = -0.4
    elif word in {'污染', '污染物', '汚', '污'}:
        value = -0.85  # Chinese/Japanese pollution and soiling
    elif word == '涉':
        value = -0.45  # wade / be involved
    elif word in {'幽', '濃'}:
        value = -0.95  # secluded/dim; dense/concentrated
    elif word in {'jurisdictional'}:
        value = -0.4

    elif word in {'says', 'shown', 'seen', 'findings'}:
        value = 0.13
    elif word in {'figure', 'figures', 'consideration', 'considerations'}:
        value = 0.2
    return None, float(value)

programs.haiku:
"""Layer 0, MLP down_proj, component 2061: word-internal pieces of split words.

The component reads a token that continues a word which the tokenizer split into
pieces: no leading space, letters, and the previous token ends in a letter. Its
activation depends on what the piece is:
  - a plural "s"/"S" after a stem: positive, larger after longer stems (about +0.2 to +0.7);
  - a noun-forming suffix piece (-ion, -ation, -ure, -ity, -ator, -ment, -ance, ...): about +0.2;
  - another plural-looking piece ending in s/es/ers/ies: about +0.15;
  - a piece that follows a punctuation-led fragment (e.g. "_com" + "poser", "-re" + "po"): about +0.12;
  - any other all-caps piece (e.g. "AMS", "ERS"): about +0.08;
  - other lower-case pieces, whole words, digits, punctuation, text in other scripts: 0.
Plain English suffixes after whole words (-ing, -er, -ly, -ful) are not positive.

The program is stateless: it reads only the current and the previous token.
"""

READS = ()

NOUN_SUFFIXES = {
    "ion", "ions", "ation", "ations", "ity", "ities", "ure", "ures",
    "ator", "ators", "ance", "ances", "ence", "ences", "ment", "ments",
    "ism", "isms", "ist", "ists",
}
NOT_PLURAL_ENDINGS = ("is", "us", "as", "ss", "os")  # -is, -us, -as, -ss, -os are not plurals


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, 0.0  # a new document starts a new word
    cur = prefix.token_strings[t]
    prev = prefix.token_strings[t - 1]
    continues_word = cur[:1].isalpha() and not cur.startswith(" ") and prev[-1:].isalpha()
    if not continues_word:
        return carry, 0.0
    low = cur.lower()
    if cur in ("s", "S"):
        return carry, 0.2 + 0.05 * min(len(prev), 10)
    if low in NOUN_SUFFIXES:
        return carry, 0.2
    if cur[-1:] in ("s", "S") and 2 <= len(cur) <= 5 and low[-2:] not in NOT_PLURAL_ENDINGS:
        return carry, 0.15
    if not prev[0].isalpha() and not prev.startswith(" "):
        return carry, 0.12
    if len(cur) >= 2 and cur.isupper():
        return carry, 0.08
    return carry, 0.0

programs.sol:
"""Detect written numerical suffixes, especially digits attached to Latin names.

An ordinary digit is strongest immediately after a letter or underscore,
weaker after punctuation, and nearly absent within a number or after a space.
Superscripts and subscripts also count as numerical suffixes.  The estimates
use the two preceding token spellings, case, spacing, and familiar
mathematical/encoding forms. Everything else is predicted as zero.
The decoded prefix is used only to recognize byte-split numerical characters.
Token-specific effects and longer-range context are not modeled.
"""
import unicodedata

READS = ()
ASCII_DIGITS = '0123456789'
SUBSCRIPTS = '₀₁₂₃₄₅₆₇₈₉'
SUPERSCRIPTS = '⁰¹²³⁴⁵⁶⁷⁸⁹'
FULLWIDTH = '０１２３４５６７８９'
FUNCTION_WORDS = {
    'a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in',
    'is', 'of', 'on', 'or', 'the', 'to', 'with',
}
MATH_WORDS = {'mod', 'sqrt'}
VARIABLES = {'x', 'y', 'z', 'n', 'i', 'j', 'k', 'r'}

# (Characters, estimate without leading space, estimate with leading space.)
DELIMITERS = (
    ('.,', 0.01, 0.22),       # Decimal points and commas.
    ('+-−–', 0.38, 0.03),    # Signs and hyphens.
    ('*/^×', 0.50, 0.34),    # Arithmetic operators.
    ('([{', 0.15, -0.06),    # Opening brackets.
    (')]}', 0.67, 0.67),     # Closing brackets.
    ("\"'`", 0.53, 0.43),   # Quotes.
    (':;', 0.19, 0.19),      # Colons and semicolons.
    ('#&%', 0.66, 0.60),     # Label/encoding markers.
    ('$€£¥', 0.42, 0.10),    # Currency signs.
    ('<>=|', 0.02, 0.02),    # Relation/separator symbols.
)


def numeric_suffix(s, previous, earlier=""):
    """Estimate a suffix from this token and the preceding two spellings."""
    c = previous[-1:] or '\0'
    word = previous.strip()
    latin = c.isascii() and c.isalpha()
    after_word = bool(earlier) and earlier[-1].isascii() and earlier[-1].isalpha()
    if s in SUBSCRIPTS and len(s) == 1:
        return (2.20 if s == '₁' else 1.85) if latin else 1.05
    if s in SUPERSCRIPTS and len(s) == 1:
        return (1.20 if s == '³' else 1.08) if latin else 0.71
    if s in FULLWIDTH and len(s) == 1:
        return 0.60
    if s not in ASCII_DIGITS or len(s) != 1:
        return 0.0

    # Small differences between the ten digit shapes.
    shape = 0.04 if s in '0123458' else 0.0
    if not previous:
        if s in '12':
            return 1.01
        return 0.13 if s in '035' else -0.05
    if latin:
        value = 1.95 + shape
        if s == '1':
            value += 0.53
        elif s == '2':
            value += 0.40
        elif s in '034':
            value += 0.22
        if len(word) == 1:
            value += 0.35
        if previous[0].isspace():
            value -= 0.33
        if c.isupper():
            value -= 0.24
        if len(word) > 1 and word.isupper():
            value += 0.60
        if word in VARIABLES:
            value -= 0.31
        if word == 'x':
            value -= 0.31
        if '\\' in previous:
            value -= 1.53
            if word.startswith('\\x'):
                value -= 0.30
        # Short consonant abbreviations resemble identifiers; longer words
        # and grammatical/operator words are weaker numerical-name prefixes.
        letters = ''.join(ch for ch in word if ch.isascii() and ch.isalpha())
        if len(letters) >= 4:
            value -= 0.30
        if 2 <= len(letters) <= 3 and letters.islower():
            if not any(ch in 'aeiou' for ch in letters):
                value += 0.35
        if word.lower() in FUNCTION_WORDS | MATH_WORDS and len(word) > 1:
            value -= 0.75
        if word.startswith('/'):
            value += 0.40
        return value
    if c == '_':
        value = 1.09 + shape
        value += 0.42 if s == '1' else 0.19 if s == '2' else 0.04
        if len(previous) > 1:
            value += 0.26
        return value
    if c.isnumeric():
        return -0.04 + shape + (0.23 if after_word else 0.0)
    if c.isspace():
        value = -0.02 + shape
        if c in '\n\r':
            value -= 0.07
        if after_word and previous == ' ':
            value += 0.08
        return value
    if c.isalpha():
        name = unicodedata.name(c, '')
        scripts = ('GREEK', 'CYRILLIC', 'KATAKANA', 'HANGUL', 'LATIN')
        if name.startswith(scripts):
            return 1.45 + (0.20 if s == '1' else 0.0)
        if name.startswith('HIRAGANA'):
            return 0.60
        return 0.30 + shape

    # Operators and delimiters are less name-like than letters.
    value = 0.35
    for characters, unspaced, spaced in DELIMITERS:
        if c in characters:
            value = spaced if previous[0].isspace() else unspaced
            break
    if after_word and previous in {'.', '-', ':', '('}:
        value = {'.': 0.74, '-': 0.78, ':': 0.56, '(': 0.19}[previous]
    if '_{' in previous:
        value = 0.95
    return value + shape


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier = '', ''
    else:
        previous, earlier = carry[1:]
    s = prefix.token_strings[-1]
    value = numeric_suffix(s, previous, earlier)
    # Byte-split Unicode digits are recognizable when their last byte arrives.
    if '\ufffd' in s and previous:
        decoded = prefix.text_prefixes[-1][-1:]
        if decoded in SUBSCRIPTS and len(decoded) == 1:
            value = 3.0 if decoded == '₃' else 2.1
        elif decoded in SUPERSCRIPTS and len(decoded) == 1:
            value = 1.15
        elif decoded in FULLWIDTH and len(decoded) == 1:
            value = 0.60
    return (doc, s, previous), float(value)

"""Predict a local contrast between dependent clauses and compressed phrases.

A recent conditional, temporal or relative clause opener raises the value on
be/have auxiliaries. Opener recency, subject pronoun and verb form scale it.
Completing familiar connectors instead gives negative values: strongest for
'because of', weaker for 'due to', 'if necessary' and duration phrases.
Three Chinese causal/time connectors also receive negative values. Small
contraction offsets cover weaker responses. These are approximate grammatical
rules, not a general parser. Keep ten tokens; reset at document boundaries.
"""
import re

READS = ()
VERBS = {
    'is': 1.0, 'are': .92, 'was': .69, 'were': .56,
    'am': .70, 'have': .64, 'has': .35, 'had': .35, 'be': .33,
    "'s": .85, "'re": 1.10,
    "'ve": .61, "'m": .74,
}
OPENERS = {
    'when': 1.03, 'if': .74, 'unless': .55, 'until': .62,
    'whether': .61, 'once': .47, 'after': .43, 'before': .21,
    'since': .44, 'while': .30, 'where': .37, 'who': .28,
    'whenever': .58, 'suppose': .28,
}
# Complete familiar abbreviated conditions and multiword connectors.
CONNECTORS = {
    'because of': -5.4, 'because that': -2.45, 'due to': -.76,
    'owing to': -.45, 'so that': -.87, 'as of': -1.05,
    'since then': -2.32, 'because then': -1.7,
    'until now': -2.4, 'for now': -1.7, 'from now': -.8,
    'so far': -.90, 'as far': -.55, 'as long': -.50,
    'as soon': -.55, 'once again': -.84, 'do so': -.42,
    'if necessary': -1.5, 'if so': -1.5, 'if then': -1.5,
    'if not': -1.22, 'if needed': -1.22, 'if required': -1.22,
    'if possible': -.76, 'if err': -.52, 'if applicable': -.85,
    'if none': -.75, 'if ever': -1.05, 'when compared': -.68,
    'as per': -.87, 'for more': -.67, 'for sure': -.72,
    'for free': -.52, 'for better': -.70, 'for once': -.65,
    'before long': -.55, 'for today': -.55, 'every now': -.50,
    'after about': -.90, 'the meantime': -.70,
}
DURATIONS = set('year years month months week weeks decade decades'.split())


def response(word, words):
    previous = words[-1].lower() if words else ''
    pair = previous + ' ' + word
    if pair in CONNECTORS:
        return CONNECTORS[pair]
    if previous == 'if' and '!' in word:
        return -.80
    if word == 'that':
        if previous in {'after', 'since', 'until'}:
            return -1.65
        if previous in {'if', 'when', 'for', 'before'}:
            return -1.1
        if previous == 'suppose':
            return -1.05 if words[-1][0].isupper() else -.6
        if previous in {'do', 'does', 'assuming'}:
            return -.65
        if previous in {'in', 'at', 'to', 'of', 'with', 'than', 'but', 'like'}:
            return -.35
    if (word == 'year' and len(words) > 1 and previous == 'a'
            and words[-2].lower() == 'once'):
        return -1.2
    if word in DURATIONS:
        scale = .75 if word in {'week', 'weeks', 'decade', 'decades'} else 1.0
        amount = -.17
        if previous in {'for', 'after'}:
            amount = -1.6 if previous == 'for' else -1.9
        if previous == 'per':
            amount = -.95
        elif previous in {'last', 'next', 'recent'}:
            amount = -.82
        elif previous == 'that':
            amount = -.72
        elif previous in {'a', 'of', 'following', 'previous'}:
            amount = -.4
        return scale * amount
    if word in {'moment', 'while'} and previous == 'a':
        if len(words) > 1 and words[-2].lower() == 'for':
            return -.8 if word == 'moment' else -.5
    if word in {'reason', 'reasons'} and 'for' in [s.lower() for s in words[-6:]]:
        return -1.2
    if word == 'or' and 'whether' in [s.lower() for s in words[-8:]]:
        return .9
    if word == '-old' and previous == 'year':
        return -.62
    if (word == 'of' and previous in
            {'year', 'years', 'month', 'months', 'week', 'weeks'}):
        # 'years of', 'months of', and similar time-measure phrases.
        return -.65
    if word == 'of' and previous in {'time', 'period', 'couple', 'pair', 'means'}:
        return -.36
    if word == 'of' and previous == 'that':
        return -.49
    if word in {'因为', '自从', '由于'}:
        return -.55
    if word not in VERBS:
        return 0.0
    strength = 0.0
    for distance, opener in enumerate(reversed(words[-8:])):
        if opener.lower() in OPENERS and not opener.isupper():
            decay = (.8, 1, .84, .56, .34, .2, .13, .1)[distance]
            strength = OPENERS[opener.lower()] * decay
            strength *= 1.12 if opener[0].isupper() else 1.0
            break
    subject = 2.0 if previous == 'you' else .83 if previous == 'there' else 1.0
    if previous in {'i', 'it', 'he', 'she', 'we', 'they'}:
        subject = 1.35
    if previous == 'who':
        subject = 3.24
    baseline = -.04 if word in {'was', 'were', 'has', 'had'} else 0.0
    if word == "'s":
        if previous not in {'it', 'that', 'there', 'who', 'he', 'she', 'what'}:
            strength *= .15
        baseline = .10 if previous in {'it', 'that', 'he', 'she'} else -.02
    if word == "'re":
        baseline = .25 if previous == 'you' else .07
    return baseline + VERBS[word] * subject * strength


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = [] if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1].replace('’', "'")
    word = token.strip().lower()
    words = re.findall(r'[A-Za-z]+|[0-9]+', ''.join(history).replace('\\n', ' '))
    value = response(word, words)
    if (word == 'of' and words and words[-1].lower() == 'because'
            and history[-1].strip() in {',', '\\n'}):
        value = -2.0
    fragment = token in {'is', 'am', 'are', 'was', 'were', 'have',
                         'has', 'had', 'be'}
    capitalized = word in VERBS and token.strip()[0].isupper()
    if fragment or capitalized:
        value = 0.0  # Word fragments in identifiers are not separate verbs.
    if token == 'Of' and history and history[-1] == 'Because':
        value = -2.9
    if token == ' ' and words and words[-1].lower() == 'since':
        value = -.7
    return (document, (history + [token])[-10:]), float(value)

programs.haiku:
"""Layer-0 MLP component 2063 (a down_proj output direction).

What it does, in plain terms: it is mostly quiet. It dips sharply negative on the word
"of" in "because of" (about -5, the one large event), and more weakly negative on the
second word of other connective and time phrases: "as of", "due to", "so that",
"after that", "if necessary", "if not", "so far", "once again", "since then", "for years",
"last year", "years of". It is positive on a form of "be" or "have" right after a
pronoun, most strongly "you are" / "you're" / "who is" (about +0.6 to +1).
"""
READS = ()

BECAUSE_OF = -5.3
CONNECTIVE_BEFORE_THAT = {"so", "for", "after", "if", "suppose", "do", "like", "because", "since"}
CONDITION_AFTER_IF = {"necessary", "needed", "required", "applicable", "possible", "not", "so", "true", "far"}
TIME_UNITS = {"year", "years", "month", "months", "week", "weeks", "decade", "decades", "day", "days"}
TIME_BEFORE = {"last", "next", "per", "for", "recent", "several", "past", "coming", "since"}
PRONOUNS = {"you", "who", "i", "we", "he", "they", "it"}
BE_HAVE = {"are", "were", "is", "was", "am", "have", "'re", "’re", "'s", "’s", "'m"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if prev == "because" and cur == "of":
        return carry, BECAUSE_OF
    if cur == "of" and prev in ("as", "that"):
        return carry, -0.8
    if cur == "that" and prev in CONNECTIVE_BEFORE_THAT:
        return carry, -1.0
    if cur in ("now", "then") and prev in ("since", "until", "for"):
        return carry, -1.5
    if prev == "due" and cur == "to":
        return carry, -0.8
    if prev in ("if", "as", "when", "why") and cur in CONDITION_AFTER_IF:
        return carry, -1.0
    if cur == "(!":
        return carry, -0.7
    if cur == "of" and prev in TIME_UNITS:
        return carry, -0.6
    if cur in TIME_UNITS and prev in TIME_BEFORE:
        return carry, -0.8
    if cur == "far" and prev in ("so", "as"):
        return carry, -0.8
    if cur == "again" and prev == "once":
        return carry, -0.9
    if cur == "more" and prev == "for":
        return carry, -0.6
    if prev == "you" and cur in ("are", "'re", "’re", "were"):
        return carry, 0.8
    if prev in ("who",) and cur in ("is", "are", "was", "were", "has", "have"):
        return carry, 0.6
    if prev in PRONOUNS and cur in BE_HAVE:
        return carry, 0.3
    return carry, 0.0

programs.luna:
"""Use recurring causal and conditional phrases as cues for sparse activations."""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    word = prefix.token_strings[-1]
    text = (tail + word)[-80:]
    lower = text.lower()
    value = 0.0

    if lower.endswith("because of"):
        value = -5.0
    elif lower.endswith("because then"):
        value = -1.5
    elif lower.endswith("for now"):
        value = -1.5
    elif lower.endswith("due to"):
        value = -0.8
    elif lower.endswith("if you're"):
        value = 1.6
    elif lower.endswith("if you are"):
        value = 1.4
    elif lower.endswith("when you are"):
        value = 1.2
    elif lower.endswith("when it is"):
        value = 1.0
    elif lower.endswith("when she is"):
