programs.sol:
"""Recognize a closing square bracket, especially a nonempty bracketed span.

Bare closers, identifier subscripts, numeric references, and Markdown link
boundaries are strong positive cues. Empty pairs and closers bundled with
statement-ending punctuation/newlines respond much less. Leading quotes or
other closing delimiters also weaken the response. A short, document-local
160-character text tail distinguishes identifiers from prose and numeric
references. Bare escaped closers are weaker; bare ASCII closers in the
first 64 document tokens receive a small bonus. Other tokens stay near zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent = 0, ""
    else:
        _, position, recent = carry
    token = prefix.token_strings[-1]
    state = (doc, position + 1, (recent + token)[-160:])
    value = 0.001

    if token in ("】", "］"):
        value = 0.50 if token == "】" else 0.70
    elif "]" in token and "[]" not in token:
        before, after = token.rsplit("]", 1)
        if not after:
            value = 0.58
            if token == "]":
                opening = recent.rfind("[")
                if opening < 0 or recent.rfind("]") > opening:
                    value = 0.50
                else:
                    inside = recent[opening + 1:]
                    if inside.strip().isdigit():
                        value = 0.55
                    elif inside.replace("_", "").isalnum():
                        value = 0.65
                    else:
                        value = 0.54
                if recent.endswith("\\"):
                    value = 0.31
                elif position < 64:
                    value += 0.05
            elif before.endswith((")", "}", "]")):
                value = 0.32
            elif before.endswith(('"', "'", ".")):
                value = 0.44
            if token.startswith(" "):
                value -= 0.08
        elif after == "(":       # [label](URL)
            value = 0.55
        elif after == "[":       # successive subscripts
            value = 0.16
        elif after in ("\\", "^", "{", "+", "-", "*", "/", "$", "%"):
            value = 0.26
        elif after.isalpha():    # e.g. Go's map[key]value type
            value = 0.40
        elif before.endswith(('"', "'")) and after == "\n":
            value = 0.14
        elif after in ("\n", ",", ".", ":", "=", ")", "'", '"'):
            value = 0.10
        elif after.startswith(","):
            value = 0.09
        else:
            value = 0.02
    return state, float(value)

programs.luna:
"""Mark a few words for amount, size, and vertical motion.

The strongest cues are increase/rise and decrease/fall words, with fractions
and some measures also firing. This predicts positive values only on those
lexical cues and zero elsewhere.
"""

READS = ()

UP = frozenset({
    "increase", "increases", "increased", "increasing",
    "rise", "rises", "rising", "risen", "rose",
    "ascend", "ascends", "ascending", "ascended",
    "grow", "grows", "growing", "grew", "grown",
    "climb", "climbs", "climbing", "climbed",
    "elevate", "elevates", "elevated", "elevating",
    "elevation", "elevations",
    "escalate", "escalates", "escalated", "escalating",
    "boost", "boosts", "boosted", "boosting",
    "lift", "lifts", "lifted", "lifting", "elevator", "elevators",
    "escape", "escapes", "escaped", "escaping",
    "ascension",
    "加大", "增加", "增大", "增长", "上升", "升高", "提高", "提升",
    "升", "腾", "电梯",
})

DOWN = frozenset({
    "decrease", "decreases", "decreased", "decreasing",
    "fall", "falls", "falling", "fell", "fallen",
    "drop", "drops", "dropped", "dropping",
    "decline", "declines", "declined", "declining",
    "descend", "descends", "descending", "descended",
    "descent", "downward",
    "reduce", "reduces", "reduced", "reducing",
    "lower", "lowers", "lowered", "lowering",
    "shrink", "shrinks", "shrinking", "shrank", "shrunk",
    "降低", "下降", "减少", "减小", "下滑", "降", "落",
})

OTHER = {
    "frac": 0.70, "fraction": 0.70, "fractional": 0.65,
    "cup": 0.85, "celsius": 0.53,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = ""
    if carry is not None and carry[0] == doc:
        word = carry[1]

    fired = 0.0
    started_in_token = False
    for char in prefix.token_strings[-1].lower():
        code = ord(char)
        han = 0x3400 <= code <= 0x9FFF or 0x20000 <= code <= 0x2FA1F
        if han:
            if word and not all(
                0x3400 <= ord(c) <= 0x9FFF or 0x20000 <= ord(c) <= 0x2FA1F
                for c in word
            ):
                word = ""
            word = (word + char)[-24:]
            started_in_token = True
            if any(word.endswith(term) for term in UP):
                fired = max(fired, 0.65)
            if any(word.endswith(term) for term in DOWN):
                fired = max(fired, 0.40)
        elif char.isalpha():
            if word and (
                0x3400 <= ord(word[-1]) <= 0x9FFF
                or 0x20000 <= ord(word[-1]) <= 0x2FA1F
            ):
                word = ""
            word = (word + char)[-24:]
            started_in_token = True
        else:
            if started_in_token:
                if word in UP:
                    fired = max(fired, 0.65)
                elif word in DOWN:
                    fired = max(fired, 0.40)
                else:
                    fired = max(fired, OTHER.get(word, 0.0))
            word = ""
            started_in_token = False

    if word in UP:
        fired = max(fired, 0.65)
        if not (0x3400 <= ord(word[-1]) <= 0x9FFF):
            word = ""
    elif word in DOWN:
        fired = max(fired, 0.40)
        if not (0x3400 <= ord(word[-1]) <= 0x9FFF):
            word = ""
    else:
        fired = max(fired, OTHER.get(word, 0.0))
        if word in OTHER:
            word = ""

    return (doc, word), fired

programs.sol:
"""A lexical detector for pieces, slices, sheets, and pictures.

Part/image nouns get positive activations, strongest for piece and Chinese
片. Plurals, capitals, and code-style tokens slightly change the response.
The next token 'of' can retain a part noun's response. Chinese compounds
with 片 distinguish pictures, film, chips, and fragments. Everything else
predicts zero. Only the previous token is remembered; documents reset it.
"""
READS = ()
PUNCTUATION = ' \t\n\r.,;:!?()[]{}\"\'_-'

# Singular and plural values for the strongest piece/image terms.
NOUNS = {
    'piece': (2.5, 2.3), 'sheet': (1.4, 1.5),
    'picture': (1.35, 1.75), 'pic': (1.05, 1.6),
    'patch': (1.3, 1.45), 'strip': (1.2, 1.2),
    'slice': (1.1, 1.2), 'tile': (0.95, 1.1),
    'fragment': (1.1, 1.15), 'snippet': (0.85, 1.0),
    'chip': (0.8, 0.8), 'film': (0.7, 0.75),
    'section': (0.24, 0.38), 'portion': (0.2, 0.35),
    'segment': (0.25, 0.35), 'bit': (0.1, 0.27),
}
SMALL_PIECES = {
    'flake', 'pellet', 'petal', 'strand', 'scrap', 'shard', 'chunk',
    'subsection', 'substring', 'worksheet', 'slicer',
}
IMAGES_AND_PARTICLES = {'photo', 'photograph', 'shot', 'plot', 'particle'}
PART_FORMS = {
    'sliced': 1.0, 'slicing': 0.8, 'tiled': 0.65,
    'fragmented': 1.2, 'fragmentation': 0.75,
    'pictured': 0.55, 'photographed': 0.5, 'stylesheet': 0.95,
    'stück': 1.3, '편': 1.4,  # German piece; Korean piece/episode
}

# Piece classifiers, flat objects, and image/fragment compounds.
CHINESE_PARTS = {
    # Essay/article counters and picture, photo, film, fragment nouns.
    '篇': 2.6, '一篇': 1.5, '这篇': 2.2, '下一篇': 1.4,
    '图片': 1.75, '圖片': 1.4, '照片': 1.4,
    '影片': 3.0, '碎片': 2.8, '片段': 2.3, '大片': 7.1,
    '卡片': 1.15, '名片': 0.95, '芯片': 1.45,
    '篇章': 1.8, '板块': 1.4,
    # Item, strip, chunk, segment, flat-object and portion counters.
    '件': 0.95, '条': 1.05, '條': 1.05, '块': 1.3, '塊': 1.3,
    '段': 0.75, '枚': 0.85, '份': 0.5, '牌': 1.7, '杯': 0.9,
    # Counters joined to one/two/several.
    '一张': 1.0, '两张': 1.0, '几张': 1.0,
    '一件': 1.0, '一块': 1.4, '一条': 0.8, '一段': 0.85,
    '两条': 0.65, '三条': 0.65, '一枚': 0.95,
    # Cut, break, tear, piece together; take a photograph.
    '切': 0.8, '碎': 1.0, '撕': 1.0, '拼': 0.7, '剪': 0.6,
    '拍': 0.75, '拍摄': 0.5,
}


def noun(token):
    word = token.strip(PUNCTUATION).lower()
    plural = word.endswith('s')
    stem = word[:-1] if plural else word
    if word == 'patches':
        stem = 'patch'
    return word, stem, plural


def english_value(token):
    word, stem, plural = noun(token)
    if word in PART_FORMS:
        return PART_FORMS[word]
    if stem in SMALL_PIECES:
        return 0.6
    if stem in IMAGES_AND_PARTICLES:
        return 0.3
    if stem not in NOUNS:
        return 0.0
    value = NOUNS[stem][int(plural)]
    title = token.strip()[:1].isupper()
    prose = token[:1].isspace()
    if stem == 'piece' and (not prose or (title and not plural)):
        value -= 0.55
    elif stem in {'sheet', 'strip'}:
        if not prose:
            value *= 0.6 if not title else 0.75
        elif title and not plural:
            value *= 0.75
    elif stem in {'slice', 'patch', 'chip'} and not prose:
        value *= 0.75
    if stem in {'picture', 'pic'} and title:
        value += 0.3
    if token.startswith(('.', '_')) and stem in {
        'fragment', 'slice', 'snippet', 'strip', 'patch'
    }:
        value *= 0.7
    return value


def following_of(old):
    word, stem, plural = noun(old)
    if stem in {'piece', 'picture', 'pic'}:
        factor = 0.64 if stem == 'piece' else 0.5
        return NOUNS[stem][int(plural)] * factor
    if stem in {'section', 'part', 'portion', 'area', 'region', 'bit'}:
        singular, multiple = {
            'section': (0.5, 0.8), 'part': (0.08, 0.47),
            'portion': (0.21, 0.42), 'area': (0.33, 0.5),
            'region': (0.21, 0.43), 'bit': (0.2, 0.42),
        }[stem]
        return multiple if plural else singular
    return 0.8 * english_value(old)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word, stem, plural = noun(token)
    value = following_of(old) if word == 'of' else english_value(token)
    if token == '片':
        value = 8.4
        if old.endswith(('短', '动画', '動畫', '断', '斷')):
            value = 6.1  # short/animated film, fragment
        elif old.endswith(('图', '圖', '灯', '燈')):
            value = 3.6  # picture/photographic slide
        elif old.endswith(('玻', '胶', '膠', '鸦', '鴉')):
            value = 6.4  # glass slide, photographic film, opium
        elif old.endswith('晶'):
            value = 4.8  # chip
        elif old == '片':
            value = 9.8  # piece after piece
    elif token in {'一片', '这片', '這片'}:
        value = 8.2 if token == '一片' else 7.7
    elif token in CHINESE_PARTS:
        value = CHINESE_PARTS[token]
    return (doc, token), float(value)

programs.luna:
"""Predict a sparse cue for pictures and named pieces of a whole.

The strongest visible vocabulary groups include pictures, images, fragments,
slices, sections and pieces. The cue is much more context-sensitive than these
words alone, so this deliberately simple rule only estimates their average rise.
"""

READS = ()

PICTURES = {"picture", "pic", "image", "photo", "film", "shot",
            "图片", "圖片", "图像", "圖像"}
PARTS = {"piece", "pieces", "fragment", "section", "sections",
         "subsection", "segment", "segments", "slice", "sliced",
         "slicer", "strip", "strips", "snippet", "portion",
         "portions", "tile", "一片", "一张", "一枚"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(
        " \t\r\n.,;:!?()[]{}\"'`"
    ).lower()
    if word == "一片":
        return None, 7.7
    if word in PICTURES:
        return None, 1.3
    if word in PARTS:
        return None, 1.2
    if word == "of" and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].strip().lower()
        if previous in {"parts", "pieces", "portions", "sections"}:
            return None, 0.4
    return None, 0.0

"""Use the few Chinese phrase cues that recur in large-response examples.
Most notably, editorial self-reference ('小编') predicts a negative response;
'的结果' predicts a positive one. The component otherwise stays near zero."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if "小编" in word:
        return None, -0.76
    if word == "的结果":
        return None, 0.82
    return None, 0.0

programs.sol:
"""An English auxiliary-verb detector, strongest on finite forms of 'be'.

The approximation uses the form and nearby grammatical surface clues:
pronoun/relative-word subject clues, modals before 'be', and negative endings.
Participles are weak. 'Had', 'would', and auxiliary contractions also respond.
Wordlike subjects receive a modest length adjustment.
The small numeric tables are average amplitudes for these grammatical classes,
not vocabulary IDs. State keeps only four preceding tokens of this document.
Unrecognized tokens get zero; weak background and non-English signals are omitted.
"""
READS = ()

# Columns: is, are, was, were. Classes use the preceding token as a
# surface clue, not a full grammatical parse. Fragments include math symbols.
SUBJECT_RESPONSE = {
    'content': (1.65, 2.47, 1.58, 1.96),
    'fragment': (1.37, 2.04, 1.37, 1.72),
    'relative': (1.22, 1.96, 1.27, 1.58),
    'what': (0.90, 1.10, 0.71, 0.75),
    'it': (1.31, 2.10, 1.36, 1.34),
    'there': (1.56, 1.80, 1.38, 1.43),
    'here': (1.31, 1.58, 1.12, 1.60),
    'this': (1.50, 2.10, 1.44, 1.55),
    'he_she': (1.83, 2.10, 1.80, 1.70),
    'they': (1.65, 2.70, 1.58, 2.13),
    'personal': (1.40, 2.27, 1.58, 1.69),
    'conjunction': (1.28, 2.02, 1.40, 1.74),
}
FINITE = {'is': 0, 'are': 1, 'was': 2, 'were': 3}
CAPITALIZED = {'is': 1.08, 'are': 1.82, 'was': 0.79, 'were': 1.43,
               'am': 0.38, 'be': 0.05, 'had': 0.61, 'would': 0.45}
MODAL_BE = {
    'to': 1.14, 'can': -0.22, 'could': 0.62, 'will': 1.38,
    'would': 1.57, 'should': 1.40, 'may': 1.46, 'might': 1.58,
    'must': 1.27, 'shall': 1.44, 'cannot': 0.29,
}
NEGATIVE_STEMS = {'isn': 0.86, 'aren': 1.10, 'wasn': 0.79, 'weren': 0.79}
NEGATIVE_ENDINGS = {'isn': 1.61, 'aren': 1.84, 'wasn': 1.43,
                    'weren': 1.63, 'wouldn': 0.62, 'hadn': 0.56,
                    'haven': 0.40, 'hasn': 0.38, 'shouldn': 0.19}


def subject_class(word):
    if word in {'which', 'who', 'that'}:
        return 'relative'
    if word in {'he', 'she'}:
        return 'he_she'
    if word in {'i', 'we', 'you'}:
        return 'personal'
    if word in {'and', 'or', 'but'}:
        return 'conjunction'
    if word in {'what', 'it', 'there', 'here', 'this', 'they'}:
        return word
    return 'content' if word.isalpha() and len(word) > 2 else 'fragment'


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().replace('’', "'")
    lower = word.lower()
    previous = history[-1].strip().lower() if history else ''
    separated = token[:1].isspace() or (history and not history[-1][-1:].isalpha())
    value = 0.0

    if lower in CAPITALIZED and word[:1].isupper():
        value = CAPITALIZED[lower]
        if word.isupper() and not separated:
            value *= 0.35
        elif word.isupper() and token.startswith(' '):
            value = {'is': 1.25, 'are': 2.50, 'was': 0.77,
                     'am': 0.17, 'be': 0.29}.get(lower, value)
    elif lower in FINITE:
        column = FINITE[lower]
        kind = subject_class(previous)
        value = SUBJECT_RESPONSE[kind][column]
        if kind == 'content':
            length_adjustment = min(len(previous), 7) - 6
            value += (0.04, 0.10, 0.025, 0.05)[column] * length_adjustment
            if history and not history[-1][:1].isspace():
                value -= 0.08
        if not separated:
            value = 0.12
    elif lower == 'am':
        value = 2.32 if previous == 'i' else 0.55
        if history and history[-1].strip() == 'i':
            value = 1.58
        if not separated:
            value = 0.07
    elif lower == 'be':
        value = 0.58
        for distance, before in enumerate(reversed(history), 1):
            modal = before.strip().lower()
            if modal in MODAL_BE:
                decay = 0.7 if modal == 'can' else 0.8
