# A rolling script cue, not a full language classifier.
SLAVIC_MARKS = frozenset('ąęłńśźżćčřěůťďň')
VOWELS = frozenset('aeiouyıаеиоуыэюяёі')


def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if unicodedata.category(c) != 'Mn')


def response(raw, previous, slavic):
    s = raw.strip().lower()
    if 'з' in s:
        if s == 'из':
            return -4.45 if raw != raw.lstrip() else -4.0
        if len(s) == 1:
            before = previous[-1:] if raw == raw.lstrip() else ''
            if before == 'И':
                return -4.35
            return -2.4 if before.lower() in {'и', 'і', 'ы'} else -0.9
        if s.startswith('з') and raw == raw.lstrip() and len(s) <= 3:
            return -1.05
        if s.endswith('из'):
            return -1.0 * min(1.0, 3.0 / len(s))
        return -0.15 if s.endswith('з') else 0.0
    if 'z' not in s:
        return 0.0
    j = s.index('z')
    n = len(s)
    if j == 0 and raw != raw.lstrip():
        if n > 3 or raw != raw.lower():
            return 0.05
        return -1.0 if slavic else -0.1
    if n > 4:
        return 0.0
    before = plain(s[j-1] if j else previous[-1:])
    if j == 0 and previous.lower().endswith(('pr', 'gr')):
        return 3.2 if n <= 2 else 2.3
    after = s[j+1:]
