        if not after:
            if before in 'iı':
                return -2.8 if n == 2 else -1.15
            if before in 'uyo' or plain(s) != s:
                return -1.1
            return -0.35
        if before in 'iı' and not after.startswith('e'):
            return -1.15
        return -0.7 if j == 0 and not after.startswith('e') else -0.08
    if before.isalpha() and j == 0:
