    'will would': (0.46, 0.12, 0.44, -0.035),
    'may might': (0.16, 0.04, 0.30, -0.02),
    'should must shall': (0.25, 0.08, 0.35, -0.02),
    'has had': (0.28, 0.14, 0.28, -0.04),
    'have': (0.18, 0.08, 0.21, -0.03),
    'do does did': (0.32, 0.16, 0.25, -0.02),
}
VERBS = {word: values for group, values in PHRASES.items()
         for word in group.split()}
CONDITIONS = set('if when where since unless until once'.split())
PRONOUNS = set('it this there he she they you we i'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, earlier = carry
    token = prefix.token_strings[-1].replace('’', "'")
    word, before = token.strip(), previous.strip().lower()
    negative = word in {'isn', 'aren', 'wasn', 'weren'}
    base = word[:-1] if negative else word
    value = 0.0
    if base in VERBS and (token[:1].isspace() or word == "'s"):
        that, which, conjunction, value = VERBS[base]
        if before == 'that':
            value = that
        elif before == 'which':
            value = which
        elif before in {'and', 'but'}:
            value = conjunction * (0.85 if before == 'but' else 1.0)
        elif before in CONDITIONS:
            value = 1.3 * that
        elif before in {'as', 'then', 'or', 'so'}:
            value = 0.55 * conjunction
        elif before in {'who', 'why', 'here', 'each', 'whatever', 'whichever'}:
            value = 0.4 * conjunction
        elif before.endswith(','):
            value = 0.3 * conjunction
        if before in PRONOUNS and earlier in CONDITIONS:
            value = 0.32 * that
        if word == "'s" and before == 'let':
            value = -0.04  # "let's" means "let us", not "let is".
        if negative:
            value *= 0.65
    elif token == ' =':
        if previous.isspace():
            value = 0.70
        elif before.endswith(')'):
            value = 0.0
        elif before.isdigit():
            value = 0.09
        elif len(before) == 1 and before.isalpha():
            value = 0.22
        else:
            value = 0.40
    elif token == '=':
        value = -0.11 if before.isdigit() else 0.0
    elif word == '是':
        value = 0.65 if before in {'，', ','} else 0.22
    return (doc, token, before), float(value)

