"""Sparse text cues: an equals sign, Chinese 是, or linked English be forms."""

READS = ()

COPULA_STRENGTH = {
    "is": 1.1,
    "are": 0.78,
    "was": 0.7,
    "were": 0.6,
    "'s": 0.78,
    "’s": 0.78,
    "是": 0.44,
}
RELATIVE_WORDS = {"that", "which"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_document = (
        prefix.position > 0
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    previous = (
        prefix.token_strings[-2].strip().lower() if same_document else ""
    )

    if word == "=":
        return None, 0.27
    if word not in COPULA_STRENGTH:
        return None, 0.0
    if word == "是":
        return None, COPULA_STRENGTH[word]

    if previous in RELATIVE_WORDS:
        return None, COPULA_STRENGTH[word]
    if previous in {"and", "but"}:
        return None, 0.8
    if previous in {"who", "whom"}:
        return None, 0.45
    if previous == ",":
        return None, 0.3
    return None, 0.0

