"""Detect chat/message boundaries and, more weakly, explicit examples.

Message and reasoning/tool delimiters produce the largest positive responses.
A message ending immediately after a tool block is stronger than one after
ordinary sentence punctuation. New documents start with a weaker opening
marker; some boundary amplitudes grow slowly with document position.
Smaller responses occur at 'for example/instance', dotted code names,
and carriage-return-heavy formatting. Other tokens receive a near-zero baseline.
"""
from math import log1p

READS = ()

FILE_ENDINGS = frozenset(
    "py js ts java cs h c cpp go rb rs sh txt json xml yaml yml md html css".split()
)
DOMAIN_ENDINGS = frozenset("com org net edu gov io".split())

MARKERS = {
    '<tool_call>': -0.098,
    '</tool_call>': 1.165,
    '<tool_response>': 0.806,
    '</tool_response>': 2.175,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, cr_count = 0, '', 0
    else:
        _, pos, previous, cr_count = carry
    cr_count += s == '\r'
    age = log1p(pos) / 6.24
    value = -0.001
    if s in MARKERS:
        value = MARKERS[s]
    elif s == '<think>':
        value = 1.94 + 0.104 * age
    elif s == '</think>':
        value = 2.331 + 0.125 * age
    elif s == '<|im_start|>':
        value = 1.6053 if pos == 0 else 1.79 + 0.084 * age
    elif s == '<|im_end|>':
        value = 2.837 + 0.265 * age
        if previous == '</tool_call>':
            value += 0.124
        elif previous == '</tool_response>':
            value += 0.154
        elif previous.rstrip().endswith(('.', '?', '。', '？')):
            value -= 0.171
        elif previous.rstrip().endswith(('!', '！', '"', "'", ')', ']', '}')):
            value -= 0.079
    elif s in (' example', ' instance') and previous.strip().lower() == 'for':
        value = 0.72 if s == ' example' else 0.79
        value += 0.05 if previous.strip() == 'For' else -0.05
    elif s == '例如':
        value = 0.284
    elif (previous + s).strip().casefold().endswith('например'):
        value = 0.40
    elif s == '.g' and previous.strip().casefold() == 'e':
        value = 0.24
    # A leading dot suggests a member name; capitals and length strengthen it.
    elif s.startswith('.') and s[1:].isidentifier():
        name = s[1:]
        value = 0.005 + 0.012 * min(len(name), 8)
        if name[0].isupper():
            value += 0.278
            if len(name) == 1:
                value -= 0.265
        if name in FILE_ENDINGS:
            value -= 0.045
        elif name in DOMAIN_ENDINGS:
            value -= 0.098
    # Repetitive formatting: how much of this document consists of returns?
    elif s == '\r':
        value = 0.60 * (cr_count / (pos + 1)) ** 1.3
    return (doc, pos + 1, s, cr_count), float(value)

programs.haiku:
"""Layer-0 MLP unit 2084 (down_proj component): an English word-ending detector.

Fires on a subword token that finishes a word written in Latin letters: a piece that
attaches directly to the letters before it, with no space in between, as the endings
in simpli|fied, cultur|al, real|ize|ation, prob|able, happi|ness, personal|ity or
walk|ing. How strongly depends on two things:
  * which ending it is: Latinate derivational endings (-ify, -ious, -ous, -able, -ity,
    -ness, -ize, -ization) fire strongest; inflections and common endings (-ing, -ed,
    -ation, -ment, -ly, -ers, -ic, -ology) fire moderately; short endings (-er, -al,
    -s, -es, -y) weakly;
  * how much word lies before it: a piece after a one- or two-letter stem (b|ed, o|s)
    is weak, one after a stem of four or more letters is at full strength.
Other pieces, whole words and non-Latin text stay at 0.
"""

READS = ()

STRONG = """ified ify ifying ious ous uous ular ously ably able ible uble ness ity ities ize ized
izing ization izer isation ised ising ance ence ium cence""".split()
MEDIUM = """ation ations ated ating ates ate ational ition ment ments ist ists ism ary ive ative
ical ic ial ial ic ing ings ed ers ly ally ically ful less ology ography ological ling ting
ged led ging ning ying ied ued ish ile ase age ature ward ancy asm mic""".split()
WEAK = "er al es s y ion ions ent ant ies ors or ine ian ter".split()
LEVEL = {}
for _s in STRONG:
    LEVEL[_s] = 1.0
for _s in MEDIUM:
    LEVEL[_s] = 0.6
for _s in WEAK:
    LEVEL[_s] = 0.25


def _ending_level(piece):
    """The strength of the ending: an exact match, else a longer ending on a stem of two or more letters."""
    if piece in LEVEL:
        return LEVEL[piece]
    for n in range(len(piece) - 2, 0, -1):
        if piece[-n:] in LEVEL:
            return LEVEL[piece[-n:]]
    return 0.0


def _letters_before(prefix):
    """Letters of the same word before the newest token, read back to the word's start."""
    count = 0
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        piece = prefix.token_strings[i]
        if piece.startswith(" "):
            count += len(piece.strip())
            break
        if not piece.isalpha() or not piece.isascii():
            break
        count += len(piece)
    return count


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    token = prefix.token_strings[-1]
    attached = prefix.token_strings[-2][-1:].isalpha() and token[:1].isalpha()
    if not (attached and token.isascii() and token.isalpha()):
        return None, 0.0
    if not (token.islower() or token.isupper()):
        return None, 0.0
    level = _ending_level(token.lower())
    stem = _letters_before(prefix)
    return None, level * min(1.0, 0.2 + 0.2 * stem)

"""Candidate 5: p4 plus weaker response to 'number' after an adjective (math sense)."""

READS: tuple[str, ...] = ()
ADJ = {"complex", "real", "whole", "prime", "natural", "integer", "composite", "rational", "irrational",
       "small", "large", "negative", "positive", "two", "three", "four", "digit", "triangular",
       "random", "phone", "maximum", "minimum", "even", "odd"}
def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    w = raw.strip(" _(-.").lower()
    if w in ("number", "numbers"):
        if w == "numbers":
            return None, -3.5
        prev = prefix.token_strings[-2].strip(" _(-.").lower() if len(prefix.token_strings) > 1 else ""
        if prev in ADJ:
