        return None, -5.5 if raw[:1].isupper() or raw.isupper() else -4.9
    if w in ("value", "values", "amount", "amounts"):
        return None, -1.0
    if w in ("num", "numerical", "numero", "número", "nombre", "zahl", "numer"):
        return None, -1.5
    return None, 0.0

