import re

READS = ()

# Each group contains conventional governors of the named preposition.
GROUPS = {
    'of': [
        (-7.7, 'capable incapable'), (-4.0, 'accused'), (-3.3, 'guilty'),
        (-2.6, 'convicted deprived'), (-2.3, 'worthy unworthy'),
        (-1.6, 'reminiscent suspected'), (-0.7, 'aware full charge'),
        (-0.9, 'proud'), (-0.4, 'instead regardless'), (-0.2, 'member'),
    ],
    'for': [
        (-5.35, 'responsible'), (-2.7, 'accountable'),
        (-1.4, 'responsibility'), (-1.1, 'known eligible liable grateful'),
        (-0.8, 'essential necessary crucial'),
        (-0.6, 'suitable important required'), (-0.5, 'need you'),
        (-0.3, 'used'),
    ],
    'with': [
        (-6.9, 'tasked'), (-5.1, 'credited'), (-3.6, 'charged'),
        (-3.4, 'concerned'), (-2.65, 'associated'),
        (-2.75, 'acquainted obsessed'), (-2.5, 'familiar unfamiliar'),
        (-1.85, 'equipped affiliated faced'), (-2.0, 'armed confronted'),
        (-1.6, 'involved adorned'), (-1.2, 'compatible filled satisfied'),
        (-1.5, 'assist'), (-1.0, 'help correlated diagnosed'),
        (-0.9, 'provided'), (-0.7, 'dealing comply'),
        (-0.5, 'completed deal'),
    ],
    'to': [
        (-1.6, 'able unable'), (-1.1, 'dedicated devoted susceptible'),
        (-1.3, 'obligated'), (-0.7, 'supposed'), (-0.5, 'willing'),
        (-0.3, 'how ability'),
    ],
    'in': [
        (-2.0, 'instrumental implicated'), (-1.6, 'interested skilled'),
        (-1.2, 'involved effective'), (-1.0, 'assist'),
        (-0.5, 'role engaged'),
    ],
    'from': [(-1.5, 'refrain exempt'), (-0.45, 'away'), (-0.7, 'apart')],
    'at': [(-3.0, 'aimed'), (-1.8, 'targeted aims')],
    'on': [(-0.8, 'focused'), (-0.5, 'focus focuses focusing')],
    'de': [(-3.2, 'capable capaz capazes'), (-3.8, 'responsable'),
           (-1.6, 'capacidad capacidade capacité')],
}
COMPLEMENTS = {
    prep: {w: strength for strength, words in groups for w in words.split()}
    for prep, groups in GROUPS.items()
}
CUES = {
    'responsible': -2.5, 'capable': -3.05, 'incapable': -2.4,
    'able': -0.5, 'unable': -0.27, 'known': -0.2,
    'accountable': -0.8, 'guilty': -0.7, 'dedicated': -0.3,
    '负责': -1.8, '負責': -1.55, 'responsable': -1.4,
    '负责任': -1.5, '负责人': -1.0, '具备': -0.9,
    'respons': -0.74, 'ponsible': -1.15,
    'في': -0.8, 'من': -0.36,  # Arabic 'in' and 'from/of'.
}
COPULAS = set('is are was were am been be'.split())
OBJECTS = set('me you him her us them it yourself themselves'.split())
PEOPLE = set('people person patients students users customers children'.split())


def background(prep, previous, first):
    if first:
        return {'with': 0.6, 'of': 0.2, 'in': 0.1, 'to': 0.1}.get(prep, 0.0)
    if previous in OBJECTS:
        return {'with': -0.65, 'of': -0.4, 'from': -0.33}.get(prep, 0.0)
    if previous in COPULAS:
        return {'of': 0.3, 'in': -0.05, 'at': -0.13}.get(prep, 0.0)
    if prep == 'with' and previous in PEOPLE:
        return -0.65
    if len(previous) > 4 and previous.endswith('ed'):
        return {'with': -0.3, 'of': -0.28, 'for': -0.15,
                'from': -0.14, 'at': -0.16, 'to': -0.06,
                'in': -0.05}.get(prep, 0.0)
    if len(previous) > 5 and previous.endswith(('able', 'ible', 'ous', 'ive')):
        return {'with': -0.27, 'for': -0.14, 'from': -0.17,
                'at': -0.17, 'in': -0.14}.get(prep, 0.0)
    return {'with': -0.13, 'from': -0.05, 'for': -0.03,
            'of': -0.015, 'at': -0.02}.get(prep, 0.0)


# Transitive governors may take an object before their preposition:
# "provide you with", "accused the girl of", "thank you all for".
OBJECT_COMPLEMENTS = {
    'with': {'provide': -0.7, 'providing': -0.7, 'provided': -0.3,
             'assist': -1.2, 'help': -0.5, 'helped': -0.5,
             'charged': -2.0, 'charging': -2.0},
    'of': {'accused': -2.2, 'accusing': -2.2},
    'for': {'thank': -0.4, 'thanked': -0.4, 'thanking': -0.4},
}


def object_complement(prep, tail):
    words = re.findall(r"[^\W\d_]+", re.split(r'[.;?!\n]', tail.lower())[-1])
    governors = OBJECT_COMPLEMENTS.get(prep, {})
    for gap in (1, 2, 3):
        if len(words) <= gap:
            break
        if any(w in {'and', 'or', 'to', 'of', 'with', 'for'}
               for w in words[-gap:]):
            break
        if words[-gap-1] in governors:
            return governors[words[-gap-1]] * (1.0, 0.6, 0.4)[gap-1]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'([^\W\d_]+)$', tail)
    previous = match[1].lower() if match else ''
    if word in COMPLEMENTS:
        value = COMPLEMENTS[word].get(previous)
        if value is None:
            value = background(word, previous, first)
            value += object_complement(word, tail)
    elif token in {'able', 'ables', 'az', 'aces', 'azes', 'áveis'}:
        value = -4.0 if previous.endswith(('cap', 'incap')) else 0.0
        if previous.endswith('respons'):
            value = -1.8
        elif token == 'able' and value == 0.0:
            value = -0.22
    else:
        value = CUES.get(word, 0.0)
        if previous in COPULAS:
            if word == 'responsible':
                value = -2.8
            elif word == 'capable':
                value = -3.3
            elif word == 'able':
                value = -0.62
    return (doc, (tail + token)[-48:]), value

"""Long written word pieces, especially nominalizations, and long layout runs.

The response rises steeply beyond eight or nine Latin letters. Noun-forming
endings and standalone nominal suffix pieces get an extra boost. Plural s,
-ing/-ed/-ly spellings, and internal capitals reduce it.
Other scripts have different length scales. This is a spelling/shape estimate,
not a dictionary of topics or a claim to recover every token's activation.
"""
import unicodedata

READS = ()

# Familiar noun-forming endings; the longest match takes precedence.
ENDING_BONUSES = {
    'ation': 0.52, 'ition': 0.22, 'ution': 0.50,
    'ction': 0.30, 'ption': 0.20, 'sion': 0.30,
    'tion': 0.26, 'sis': 0.36,
    'ment': 0.25, 'ness': 0.20, 'ity': 0.05,
    'ship': 0.15, 'ance': 0.05, 'ence': 0.05, 'ism': 0.07,
}
NOMINAL_FRAGMENTS = {
    'ation', 'ition', 'ution', 'ction', 'ption', 'sion',
    'ization', 'isation', 'ification', 'ulation',
    'itation', 'uration', 'mentation',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lstrip('._@-/')
    n = len(word)
    value = 0.002
    names = [unicodedata.name(ch, '') for ch in word]

    if word.isalpha() and all('LATIN' in name for name in names):
        value += (0.001 - 0.024 * max(n - 5, 0)
                  + 0.214 * max(n - 8, 0)
                  + 0.251 * max(n - 9, 0)
                  - 0.014 * max(n - 13, 0))
        if not word.isupper():
            value -= 0.14 * sum(ch.isupper() for ch in word[1:])
        lower = word.lower()
        plural = (n >= 5 and lower.endswith('s')
                  and not lower.endswith(('ss', 'ous', 'is')))
        stem = lower[:-1] if plural else lower
        value -= plural * (0.01 + 0.10 * max(n - 8, 0))
        for ending, bonus in ENDING_BONUSES.items():
            if stem.endswith(ending) and n > len(ending):
                value += bonus
                break
        if stem.endswith(('ing', 'ed', 'ly')):
            value -= 0.02 + 0.12 * max(n - 8, 0)
        if token and not token[0].isspace() and stem in NOMINAL_FRAGMENTS:
            value += 0.45
            if stem.endswith(('ification', 'ization', 'isation',
                              'ulation', 'itation', 'uration')):
                value += 0.17 * max(n - 5, 0)
    elif word and all('CYRILLIC' in name for name in names):
        value += -0.005 + 0.216 * max(n - 7, 0) ** 1.2
    elif word and all('\u4e00' <= ch <= '\u9fff' for ch in word):
        value += -0.18 if n == 3 else 0.14 if n >= 4 else 0.0
    elif word and all('HIRAGANA' in name or 'KATAKANA' in name
                      for name in names):
        value += 0.31 * max(n - 3, 0)
    elif word.isalpha():
        value += 0.17 * max(n - 7, 0)

    # Indentation and decorative separator lines are also long token shapes.
    if token and not token.strip(' \t'):
        value += 0.74 * max(min(len(token), 64) - 12, 0) / 30
    separator = text.lstrip('/') if text.startswith('/') else text
    if len(separator) > 12 and len(set(separator)) == 1:
        m = len(separator)
        if separator[0] in '-_=*#':
            if m <= 32:
                response = 0.16 * (m - 12)
            elif m <= 48:
                response = 3.2
            elif m <= 64:
                response = 3.2 - 0.15 * (m - 48)
            else:
                response = 0.8 + 0.08 * (min(m, 100) - 64)
            value += 0.97 * response
        elif separator[0] == '.':
            value += 0.094 * (m - 12)
    return None, float(max(-0.5, min(value, 5.0)))

