"""Indentation detector: fires on the first token of a line when that token is
leading whitespace (strongest for shallow indents of 1-2 columns, weakening with depth),
and, more weakly, on a few markup/table/list symbols that open a line.

Concept: layer-0 MLP neuron 2089 says "a new line has just begun with indentation or with
a structural symbol (backslash, pipe, angle bracket, dash, bracket)". Everything else is 0.
"""

READS = ()

# Leading whitespace at the start of a line, keyed by its width in columns (a tab = 4).
# Shallow indents respond most; very deep indents (13+ columns) do not respond at all.
INDENT_COLUMNS = {1: 1.8, 2: 2.35, 3: 1.3, 4: 1.7, 5: 1.0, 6: 1.0,
                  7: 0.65, 8: 0.6, 9: 0.3, 10: 0.3, 11: 0.2, 12: 0.2}

# Non-whitespace tokens that open a line in LaTeX, tables, markup, math or lists.
LINE_OPENERS = {"\\": 3.2, "|": 2.1, "</": 2.0, "$$": 1.8, "<": 1.4, "``": 1.2,
                "```": 1.0, ">": 1.0, "-": 0.7, "[": 0.6, "+": 0.6, '{"': 0.45}


def step(carry, prefix, upstream):
    """Activation at the newest token: nonzero only if the previous token ends a line
    (contains a newline) inside the same document."""
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if "\n" not in prefix.token_strings[-2] and "\r" not in prefix.token_strings[-2]:
        return carry, 0.0
    token = prefix.token_strings[-1]
    if token and token.strip(" \t\xa0") == "":
        columns = len(token.replace("\t", "    "))
        return carry, INDENT_COLUMNS.get(columns, 0.0)
    return carry, LINE_OPENERS.get(token, 0.0)

programs.luna:
"""Recognize indentation and a few common left-edge syntax markers.

The component's clearest response is to short runs of spaces at a new line:
two spaces produce the strongest estimate, with longer indentation runs
usually weaker. It also responds to list, quote, table, and code-fence marks
that open a line. This is a compact, approximate pattern detector, not a
reconstruction of the MLP.
"""

READS: tuple[str, ...] = ()

LIST_AND_LINE_MARKERS = {"-", "*", "+", "|", ">", "[", "![", "```", "@@"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]

    if carry is None or carry[0] != document:
        at_line_start = True
    else:
        at_line_start = carry[1]

    value = 0.0
    if at_line_start:
        if token and set(token) == {" "}:
            width = len(token)
            value = {2: 2.35, 3: 1.3, 4: 1.8, 7: 0.65}.get(width, 0.0)
        elif token and token.isspace() and "\t" in token:
            value = 0.9
        elif token.strip() in LIST_AND_LINE_MARKERS:
            value = 0.6

    if "\n" in token:
        tail = token.rsplit("\n", 1)[1]
        next_line_start = not tail or tail.isspace()
    elif token and not token.isspace():
        next_line_start = False
    else:
        next_line_start = at_line_start

    return (document, next_line_start), float(value)

"""A sparse lexical approximation to hope and expectation language.

The strongest responses are on hope words; expectation and related
future-looking words receive smaller scores.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()

    if "hope" in word:
        value = 3.5 if word.startswith("hoped") else 5.3
    elif "希望" in word:
        value = 7.2
    elif "期望" in word:
        value = 4.0
    elif "望" in word:
        value = 3.5
    elif word.startswith("expectation"):
        value = 2.0
    elif word.startswith("unexpected"):
        value = 0.55
    elif word.startswith("expect"):
        value = 1.5
    elif "future" in word:
        value = 0.9
    elif "esper" in word:
        value = 0.9
    elif any(term in word for term in (
        "wish", "desir", "anticipat", "dream", "prospect",
        "promis", "ambition", "forward", "今後", "未来",
    )):
        value = 0.55
    else:
        same_document = (
            len(prefix.token_ids) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        previous = prefix.token_strings[-2].casefold() if same_document else ""
        if "hope" in previous:
            value = 2.8 if raw[:1].isalnum() else 0.8
        else:
            value = 0.0

    return None, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:2092 -- a diffuse word-level feature with a small concept core.

Most of this component's variance is token-specific and spread over thousands of
ordinary words, so no short word list explains much of it. What a person can name:

* Story-character and theme words (character(s), theme(s), protagonist, hero, scene, plot,
  and 人物 / 主角 / 主题 / 角色 ...) push the activation negative, about -0.12.
* Audience, reception and writing words (audience, viewers, poetry, publishing, script,
  writing, and 观众 / 口碑 / 评分 / 出版 / 诗 ...) push it positive, about +0.09.
* Chat and tool markup closers (</think>, 》, <tool_call>) push it positive, about +0.11.

Everything else predicts 0. The program reads only the current token, so it needs no state.
"""

READS = ()

CHARACTER_THEME = {
    "character", "characters", "theme", "themes", "protagonist", "protagonists",
    "scene", "scenes", "hero", "heroes", "plot", "人物", "主角", "主题", "主人公",
    "角色", "形象", "情节",
}
RECEPTION_WRITING = {
    "audience", "audiences", "viewer", "viewers", "poem", "poems", "poetry", "publishing",
    "writing", "script", "scripts", "观众", "评分", "口碑", "作文", "创作", "出版", "豆瓣", "诗",
}
MARKUP = {"</think>", "》", "<tool_call>"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CHARACTER_THEME:
        value = -0.12
    elif word in RECEPTION_WRITING:
        value = 0.09
    elif word in MARKUP:
        value = 0.11
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A spelling detector for the syllable 'ter', especially short word pieces.

The largest responses are to 'ter' itself and the filter/alter spelling
families. Other short pieces ending in 'ter' respond less. Whole words
usually dilute this response. A few other scripts have analogous syllables.
The predictor uses only the current token, not the preceding text.
"""
import re

READS = ()

def activation(token):
    s = token.strip().strip('._-/()[]').lower()
    spaced = token[:1].isspace()
    # Korean, Cyrillic and Japanese approximations of the same sound.
    if s in {'터', 'тер', 'ター'}:
        return 1.37
    if s == 'ter':
        return 3.20 if spaced else 2.67
    if s in {'ters', 'tering', 'tered'}:
        return 1.84
    if re.fullmatch(r'f?ilters?|alters?', s):
        return 2.9
    if re.fullmatch(r'(?:f?ilter|alter)(?:ed|ing|ation|ations)', s):
        return 1.5
    if re.fullmatch(r'l[aei]tters?', s):
        return 0.95
    if re.fullmatch(r'b[iu]tter|gutter|utter', s):
        return 1.15
    if s == 'iter':
        return 1.42
    if s in {'inter', 'unter', 'heter', 'liter', 'интер'}:
        return 0.94
    if (s.startswith(('termin', 'territ'))
            or s in {'term', 'terms', 'tern', 'terr'}):
        return 0.58
    if s in {'filtr', 'filtra', 'filtration', 'филь'}:
        return 0.62
    # No leading space favors a word piece; short pieces respond more.
    if not spaced and s.isascii() and s.islower():
        if re.fullmatch(r'[a-z]{1,3}ters?', s):
            # Familiar complete words, rather than suffix fragments.
            if s in {'after', 'enter', 'water', 'later'}:
                return 0.0
            stem = s[:-1] if s.endswith('ters') else s
            if re.fullmatch(r'[aiou]t{1,2}er', stem):
                return 1.89
            if len(stem) <= 5:
                return 1.12
            return 0.27
        if re.fullmatch(r'[a-z]{0,3}ers?', s):
            return 0.14
    # Complete or longer words containing the ending are much weaker.
    if s.endswith(('ter', 'ters')):
        return 0.17
    return 0.0

def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

programs.luna:
"""Track 'ter' spelling, with a stronger response to the 'filtr-' word family."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if 'filtr' in token:
        return None, 1.8
    if 'ter' in token:
        return None, 0.35
    return None, 0.0

programs.sol:
"""Approximate an asterisk/multiplication-mark response, not arithmetic in general.

Single asterisks give the largest predictions, adjusted by preceding spacing,
letters, numbers and stars. Comment boundaries, repeated stars and stars joined
with letters, punctuation or newlines get separate, usually smaller responses.
Bullets, multiplication signs/words and separate slashes get modest predictions;
slash-word segments get a tiny negative prediction. Other tokens predict zero.

These rules capture the dominant spikes, not the diffuse small lexical effects.
State holds the previous token and 160 characters for comment-line context,
reset whenever the document changes.
"""
import re

READS = ()
DOT_MARKS = frozenset('•·・･✝☆※')
SMALL_MARKS = frozenset('⋅⊗†◦★')


def star_response(s, previous, recent, first):
    q = s.strip()
    n = s.count('*')
    if first:
        return 0.4 if q == '*' else 0.1
    if n >= 3:
        if '\n' in s:
            return 0.8 if n <= 4 else 0.25
        if '/' in s:
            return 1.3 if n <= 4 else 0.65
        if n <= 4:
            return 2.2 if s.startswith(' ') else 1.6
        return 1.0
    if n == 2:
        if '/' in s:
            return 0.3 if '\n' in s else 0.7
        if q.endswith((':', ',', '.')):
            return 0.15
        if s.startswith(' '):
            return 0.9
        word = previous.strip()
        if '*' in previous or (word.islower() and len(word) == 1):
            return 0.4
        return 0.75
    if '/' in s:
        if '\n' in s:
            return 1.5 if s.startswith(' ') and q.startswith('/*') else 0.57
        if q.startswith('*/'):
            return 1.1 if s.startswith(' ') else 1.75
        return 1.96
    if '\n' in s:
        return 1.4
    if q == '*':
        spaced = s.startswith(' ')
        if '*' in previous:
            return 0.5
        if previous.isspace():
            if not spaced:
                return 2.44
            if '\t' in previous:
                return 1.93
            if '\n' in previous:
                return 1.55
            if re.search(r'/\*+\s*$', recent):
                return 0.75
            if re.search(r'\n\s*\*\s*\n\s*$', recent):
                return 1.17
            line = recent.rsplit('\n', 1)[-1]
            return 2.14 if not line.strip() else 2.6
        if previous.strip().isdigit():
            return 2.65 if spaced else 2.23
        if previous.endswith('\n'):
            return 1.55 if spaced else 2.44
        if spaced:
            return 3.26
        word = previous.strip()
        if len(word) == 1 and word.isalpha() and not previous.startswith(' '):
            return 1.9
        return 2.82
    if any(c.isalpha() for c in s):
        return 1.94
    if q.endswith(','):
        return 0.95
    if q.endswith('.') or q.endswith('(-'):
        return 1.9
    if q.endswith((')', '-')):
        return 1.4
    if q.endswith('('):
        return 1.98
    if q.endswith('\\'):
        return 1.75
    return 2.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, recent = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    q = s.strip()
    value = 0.0
    if '*' in s:
        value = star_response(s, previous, recent, first)
    elif q in DOT_MARKS:
        value = 0.8
    elif q in SMALL_MARKS:
        value = 0.33
    elif q == '●':
        value = 0.54
    elif q == '＊':
        value = 1.8
    elif q == '∗':
        value = 1.3
    elif q in {'／', '⁄'}:
        value = 0.36
    elif q == '乘':
        value = 0.84
    elif q == '×':
        value = 0.56
    elif q == 'cdot':
        value = 1.04
    elif q.lower() in {'multiply', 'multiplying', 'multiplied'}:
        value = 0.47
    elif q == 'times':
        value = 0.27 if s.startswith(' ') else 0.64
    elif '/' in q and q.count('/') == 1:
        if q == '/':
            if '\n' in s:
                value = 0.06
            elif s.startswith(' '):
                value = 0.505
            else:
                value = 0.287 if previous.strip().isdigit() else 0.215
        elif q.startswith('/') and q[1:].isalpha():
            value = -0.055
        elif q.endswith('/') and not any(c.isalpha() for c in q) and '<' not in q:
            value = 0.3
    return (doc, s, (recent + s)[-160:]), float(value)

programs.luna:
"""A few punctuation marks often trigger this component in math and source text."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "*" in token:
        return None, 0.7 if "/" in token else 2.2
    if "/" in token:
        return None, 0.25
    if "•" in token:
        return None, 1.0
    if "・" in token or "cdot" in token:
        return None, 0.7
    return None, 0.0

programs.sol:
"""A negative spelling response to 'gl', especially a short token fragment.

Longer gl words are weaker; ordinary glob-/gland- words are mostly exempt.
OpenGL-style code names, graphics, and three related script spellings also
respond. Small l/li/lu rules and a weaker g-to-n response are included.
A one-token memory handles split clusters and short continuations.
It resets at document boundaries; other tokens receive approximately zero.
"""
READS = ()
PUNCTUATION = "()[]{}.,;:\\/_-'\"`!?<>"
GL_VOWELS = {'i': -2.3, 'u': -2.8, 'e': -1.4, 'o': -1.0, 'y': -0.55}
SCRIPT_GL = frozenset(('гл', '글', 'กล'))
LIQUID_FRAGMENTS = {'l': -0.26, 'li': -0.75, 'lu': -0.43}


def clean(s):
    return s.strip().strip(PUNCTUATION)


def spelling_value(s):
    core = clean(s)
    word = core.lower()
    if word == 'gl':
        if s.startswith('.'):
            return -6.6
        return -4.4 if core == 'gl' else -3.3 if core == 'Gl' else -4.0
    # GL types/libraries and API calls such as glVertex or OpenGL.
    if 'GL' in core and (core.endswith('GL') or core.startswith('GL') and
                        (core[2:3].islower() or
                         core.startswith(('GLFW', 'GLUT')))):
        return -2.6
    if word.startswith('gl'):
        if core.startswith('gl') and core[2:3].isupper():
            return -2.3
        if word.startswith(('glob', 'gland')):
            return -0.1
        if len(word) == 3:
            return GL_VOWELS.get(word[-1], -1.9)
        return -1.6 if len(word) == 4 else -0.8
    if len(word) <= 5 and core.islower() and not s[:1].isspace() and \
            (word.endswith('gl') or word.endswith('gli')):
        return -1.7
    if word.startswith('graphics'):
        return -1.2
    if core in SCRIPT_GL:
        return -1.2
    return LIQUID_FRAGMENTS.get(s, 0.001)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = spelling_value(s)
    after_g = previous[-1:].lower() == 'g'
    if s[:1].lower() == 'l' and s.isalpha():
        if after_g:
            value -= (1.33, 1.14, 0.56)[min(len(s), 3) - 1]
            if previous.endswith('G'):
                value -= 0.74
        elif 'g' in previous[-8:].lower():
            value -= 0.14
    if after_g and clean(s).lower().startswith('gl'):
        value -= 0.61
    if s.isalpha() and len(s) <= 3 and clean(previous).lower() == 'gl':
        value -= 0.96
    if after_g and s[:1].lower() == 'n' and s.isalpha():
        value -= 0.39
    return (doc, s), float(value)

"""Detect greater-than signs and closing angle brackets, from token spelling.

A bare `>` gives the largest response, stronger when closing a programming
parameter type than an HTML tag. Repeated and quoted brackets are weaker;
a following newline suppresses them. Common Java reference types
give particularly strong closing-bracket responses. Arrows and joined HTML
tags do not count. 'greater', 'gt', and typographic variants also give responses.
The short text carry is reset at document boundaries.
"""
import re

READS = ()
HTML = set('a b br code div em font h1 h2 h3 hr i img li ol p pre span '
           'strong sub sup table tbody td th thead tr tt ul'.split())
JAVA_REFERENCE_TYPES = set(
    'String Object Integer Boolean Double Float Long Short Byte Character'.split()
)


def bare_bracket(tail, newline):
    match = re.search(r'<([^<>]*)$', tail)
    if match:
        inside = match[1]
        if inside.lstrip('/').lower() in HTML:
            return 0.10 if newline else 0.97
        before = tail[:match.start()]
        if re.search(r'[\w:]$|#\s*include\s*$', before):
            last_word = re.search(r'(\w+)$', inside)
            standard_type = last_word and last_word[1] in JAVA_REFERENCE_TYPES
            return (0.25 if newline else (1.83 if standard_type else 1.48))
        return 0.13 if newline else 1.15
    return 0.33 if newline else 1.23


def response(s, tail):
    w = s.strip()
    if w.lower() == 'greater':
        return 0.18
    if w == 'gt':
        return 0.83 if tail.endswith(('&', '__', '-')) else 0.24
    if w in ('＞', '≫', '»'):
        return {'＞': 0.84, '≫': 0.29, '»': 0.12}[w]
    if '>' not in s or '<' in w:
        return 0.50 if w == '<?>' else 0.0
    newline = '\n' in s or '\r' in s
    if w == '>':
        if s.startswith(' '):
            return 0.45 if newline else 1.17
        return bare_bracket(tail, newline)
    if newline:
        return 0.09 if w.endswith('>') and len(w) <= 4 else 0.0
    if set(w) == {'>'}:
        return 0.92 if len(w) == 2 else (0.43 if s.startswith(' ') else 0.65)
    if '-->' in w:
        return 0.16
    if '->' in w or '=>' in w:
        return 0.0
    if w.endswith('>'):
        if w.endswith('">'):
            return 0.54
        if w.endswith("'>"):
            return 0.89
        return 0.38 if w.endswith('/>') else 0.89
    if w.startswith('>'):
        if '=' in w:
            return 0.17
        return 0.13 if any(c in w for c in ',;{') else 0.30
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (tail + s)[-200:]), response(s, tail)

"""A whitespace-boundary detector.

Extra blanks are positive, especially successive single-space tokens in line
indentation. Space-prefixed punctuation gives a smaller response. Separately
encoded non-ASCII letters at word starts can be negative; recent Greek text
helps distinguish Greek words from isolated mathematical symbols. Most other
text is neutral. These rules approximate the large responses, not the small
word-specific fluctuations.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
BLANKS = ' \t\xa0'
PERSIAN_FORMS = frozenset('پچژگکی')
# Responses when a byte-fragment token completes a word-initial character.
FRAGMENT_SCRIPTS = {
    'KATAKANA': -1.28,
    'GURMUKHI': -1.7, 'SINHALA': -1.7,
    'TELUGU': -2.3, 'TAMIL': -2.3, 'DEVANAGARI': -2.3, 'BENGALI': -2.3,
    'LATIN': -0.6, 'CYRILLIC': -0.6, 'HEBREW': -0.6,
    'HIRAGANA': -0.72,
    'MATHEMATICAL': -0.7, 'DOUBLE-STRUCK': -0.7,
    'SCRIPT': -0.7, 'BLACK-LETTER': -0.7,
}


@lru_cache(maxsize=8192)
def greek_count(text):
    return sum('GREEK' in ud.name(c, '') for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', True, ())
    _, prev, indent, recent = carry
    token = prefix.token_strings[-1]
    greek = sum(recent) >= 3
    blank = bool(prev) and not prev.strip(BLANKS)
    n = len(prev)
    value = 0.0

    if token == ' ':
        if not prev:
            value = 1.11
        elif prev == ' ':
            value = 1.84 if indent else 1.34
        elif not prev.strip(' '):
            value = (1.0 if n == 2 else 0.87 if n <= 4
                     else max(0.35, 1.2 * n**-0.36))
        elif blank:
            value = 0.72 if n <= 2 else 0.56
        elif prev.endswith('\n'):
            value = (0.15 if not prev.strip('\n\r') else
                     0.50 if not prev.strip(BLANKS + '\n\r') else 0.05)
        elif prev.strip(' ') in ('(', '[', '{', '$', '|'):
            value = 0.45 if '$' in prev else 0.21 if '|' in prev else 0.33
        elif prev in ('-', '\\n'):
            value = 0.27
    elif token == '\xa0':
        value = (1.23 if not prev else 1.24 if prev == '\xa0'
                 else 0.90 if prev == ' ' else 0.55 if blank else 0.0)
    elif (token and not token.strip(' \xa0')
          and ' ' in token and '\xa0' in token):
        value = 0.75 if prev == '\xa0' else 0.65 if blank else 0.20
    elif token == '\t':
        value = (0.18 if not prev else 0.52 if prev == ' '
                 else 0.18/n if blank else -0.08)
    elif blank and token in (' -', ' \\', ' ('):
        value = 0.78 if n == 1 else 0.95/n
    elif blank and token in (' [', ' ]', ' <', ' >', ' |', ' $',
                            ' +', ' =', ' "', " '"):
        value = 0.42 if n == 1 else 0.35/n**0.4
    elif blank and token == '``':
        value = 0.4

    letter = token.lstrip(' ')
    boundary = token.startswith(' ') or (prev and prev[-1].isspace())
    if len(letter) == 1 and boundary and ord(letter) > 127:
        name = ud.name(letter, '')
        if 'GREEK' in name and greek:
            value = -1.27 if greek_count(prev[-1:]) else -1.05
        elif 'LATIN' in name:
            base = ud.normalize('NFD', letter)[0].lower()
            value = -0.1 if base in 'aeiouy' else -0.35
        elif letter in PERSIAN_FORMS:
            value = -0.35
        elif 'THAI' in name:
            value = -0.27

    if '\ufffd' in token and prev:
        # Decode only here: the token alone cannot identify its finished letter.
        text = prefix.text_prefixes[-1]
        char = text[-1:]
        name = ud.name(char, '')
        if len(text) >= 2 and text[-2].isspace() and char != '\ufffd':
            if 'GREEK' in name:
                value = -0.95 if greek else -0.26
            else:
                value = next((w for script, w in FRAGMENT_SCRIPTS.items()
                              if name.startswith(script)), value)
        elif char != '\ufffd' and 'KATAKANA' in name:
            value = -0.3
        elif char == '\ufffd' and greek and token.startswith(' '):
            value = -0.2

    if '\n' in token:
        indent = not token.rsplit('\n', 1)[1].strip(BLANKS)
    elif token.strip(BLANKS):
        indent = False
    recent = (recent + (greek_count(token),))[-8:]
    return (doc, token, indent, recent), float(value)

programs.luna:
"""Approximate the component's repeated-space and Greek word-start responses."""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]

    if carry is None or carry[0] != document:
        previous_char = ""
    else:
        previous_char = carry[1]

    value = 0.0
    if token == " ":
        if previous_char == " ":
            value = 0.96
        elif previous_char == "\n":
            value = 0.2
        else:
            value = 0.02
    else:
        letters = token.lstrip()
        if token.startswith(" ") and letters:
            if unicodedata.name(letters[0], "").startswith("GREEK"):
                value = -1.0

    previous_char = token[-1:] or previous_char
    return (document, previous_char), float(value)

programs.sol:
"""A lexical predictor dominated by a large negative response to 'every'.

Weaker responses cover 'each', 'any', 'very', 'no', compounds, and selected
translations. Spacing, capitalization, and a few previous-word constructions
change their strength. 'All' has a small positive response instead.
Unlisted tokens get zero: this omits the component's weak lexical background.
Only the previous token in the same document is inspected; no state is needed.
"""
READS: tuple[str, ...] = ()

# Distributive/free-choice quantifiers and their tokenized stems.
# Russian "ажд" is the middle of "каждый" (each/every).
DISTRIBUTIVE = {
    'cada': -3.4, 'ogni': -3.3,
    'chaque': -1.6, 'jeder': -1.7, 'jede': -1.7,
    'jedes': -1.7, 'jedem': -1.6,
