    elif word == 'any':
        value = -1.55 if capital else (-1.15 if spaced else -0.75)
        if previous in {'have', 'has', 'had', 'without', 'there'}:
            value = 0.0
        elif previous == 'are':
            value = 0.3
        elif previous in {'if', 'find', 'contain'}:
            value = -0.3
        elif previous in {'as', 'that'}:
            value = -1.6
        elif previous == 'than':
            value = -2.1
        elif previous in {'almost', 'nearly'}:
