    elif word == 'very':
        value = -1.55 if capital else (-1.95 if spaced else -2.8)
        if previous == 'the':
            value = -2.7
        elif previous == 'for':
            value = -1.35
        elif previous == 'not':
            value = -1.6
    elif word == 'no':
        value = -0.35 if capital else (-0.42 if spaced else -0.18)
        if previous in {'is', 'was', 'has', 'have', 'had', 'that'}:
            value = -0.64
    elif word in {'entire', 'whole', 'only'}:
        if previous == 'the':
            value = {'entire': -1.35, 'whole': -0.95, 'only': -1.03}[word]
        else:
            value = {'entire': -0.85, 'whole': -0.35, 'only': -0.1}[word]
