programs.sol:
"""A partial lexical explanation, not a general activation reconstruction.

He/She respond positively when a sentence is quoted or discussed as language;
ordinary occurrences are weak. Grammar terminology has a negative response,
with separate estimates for lowercase leading-space terms at document start.
There are also small negative responses to early timing, indefinite referents and frequency words, and distinct signs
at tool-call/reply boundaries. Uncovered lexical variation is left at zero.
Only a bounded recent text buffer is kept, reset between documents.
"""
import re

READS = ()

LANGUAGE_CUES = re.compile(
    r'\b(sentences?|grammar|grammatical|pronouns?|lexical|linguistic|'
    r'translat(?:e|ion|ions)|tenses?|nouns?|verbs?|adjectives?|adverbs?|'
    r'syntax|spelling|punctuation|common sense|make sense)\b'
)
SENTENCE_CHOICES = re.compile(r'\bsentence [ab]\b|\boptions:|\bnonsensical\b')
GRAMMAR_TERMS = {'sentence', 'sentences', 'grammar', 'grammatical',
                 'lexical', 'linguistic', 'semantics', 'spelling'}
INDEFINITE = {'anything', 'everything', 'something', 'nothing', 'anybody',
              'somebody', 'nobody', 'anyone'}
# Leading-space grammar terms at the start of a row or document.
INITIAL_GRAMMAR = {
    'sentence': -0.31,
    'sentences': -0.50,
    'grammar': -0.55,
    'lexical': -0.68,
    'linguistic': -0.53,
    'semantics': -0.31,
    'spelling': -0.11,
}
FREQUENCY = {'ever', 'never', 'always', 'often', 'sometimes', 'rarely'}
EARLY = {'early', 'earlier', 'earliest'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    if first:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    word = token.strip().lower()
    quote = previous.rstrip().endswith(('"', '“', '‘', "'"))
    value = 0.0

    if word in {'he', 'she', 'him', 'her', 'his', 'hers'}:
        discussed = bool(LANGUAGE_CUES.search(recent[-160:]))
        wider_discussion = bool(LANGUAGE_CUES.search(recent))
        capitalized = token.strip() in {'He', 'She'}
        if capitalized:
            value = 0.015 if token.startswith(' ') else 0.03
            if quote:
                value = 0.50 if discussed else 0.08
                if SENTENCE_CHOICES.search(recent):
                    value = 0.80
            elif wider_discussion:
                value = 0.10
                if previous.rstrip().endswith(':'):
                    value = 0.30
        else:
            value = -0.003
            if discussed:
                value = 0.15 if quote else 0.055
    elif word in GRAMMAR_TERMS:
        value = -0.12
        if word == 'grammar' or word == 'lexical':
            value = -0.16
        if first and token == ' ' + word:
            value = INITIAL_GRAMMAR.get(word, -0.40)
    elif word in {'language', 'languages', 'english'}:
        value = -0.03
        if LANGUAGE_CUES.search(recent[-160:]):
            value = -0.14
        if first and token == ' ' + token.strip():
            value = 0.0 if word == 'languages' else -0.23
    elif word in INDEFINITE:
        value = -0.05
    elif word in FREQUENCY:
        value = -0.06
    elif word in EARLY:
        value = -0.10
    elif word in {'online', 'website', 'websites', 'www'}:
        value = -0.09
    elif word == 'those':
        value = -0.07
    elif word in {'because', 'being'}:
        value = -0.05
    elif word == 'an':
        value = -0.024
    elif token == '<tool_call>':
        value = -0.10
    elif token == '</tool_call>':
        value = -0.113
    elif token == '</tool_response>':
        value = 0.123
    elif token in {'<think>', '</think>'}:
        value = -0.065
    elif token == '<|im_end|>':
        value = -0.029

    return (document, (recent + token.lower())[-300:], token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 2101: a weak, mostly token-specific readout.

This component has no clean concept. Its activation is small (RMS 0.033) and spread
over thousands of different tokens with mixed signs. This program predicts only the
parts that are consistent across the data, from three word groups with clearly non-zero
average activation:
  - chat/tool markup: "<tool_call>" and "</tool_call>" are negative, "</tool_response>" positive;
  - hedging and time adverbs ("ever", "never", "often", "early", "because", "being", ...):
    clearly negative;
  - common prepositions ("of", "with", "in", "to", "by", "for", "on"): slightly positive.
Every other token predicts 0. Each prediction depends only on the newest token, so the
program keeps no state across positions.
"""

READS = ()

MARKUP = {"<tool_call>": -0.10, "</tool_call>": -0.11, "</tool_response>": 0.12, "<|im_end|>": -0.03}
HEDGES = {" ever", " never", " often", " early", " earlier", " finally", " especially",
          " anything", " because", " being", " those", " an"}
PREPOSITIONS = {" of", " with", " in", " to", " by", " for", " on"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in MARKUP:
        value = MARKUP[token]
    elif token in HEDGES:
        value = -0.044
    elif token in PREPOSITIONS:
        value = 0.004
    else:
        value = 0.0
    return None, value

programs.sol:
"""An opening-of-document pulse with a smaller response to chat/tool markup.

At a document's first token, estimate ordinary text by token length, case,
script and word class. Chat boundary markers and the following role name
produce much larger pulses. Markup responses and the ordinary opening pulse
fade with distance from the document's beginning. All constants were fitted
on training text; individual ordinary words are not looked up.
"""

import unicodedata

READS = ()

FUNCTION_WORDS = frozenset('''
a an the this that these those and or but nor if so as than of in on at by
for from to with without into over under between before after about through
is am are was were be been being do does did have has had can could shall
should will would may might must not no it its they them their he him his
she her we us our you your i me my who what when where why how which
here there
'''.split())
DECLARATIONS = frozenset('''
package import using namespace class public private def function require
'''.split())

OPENING_MARKERS = {
    '<|im_start|>': 7.80,
    '<|im_end|>': 2.93,
    '<|endoftext|>': 0.41,
    '<tool_call>': 6.72,
    '</tool_call>': 5.63,
    '<tool_response>': 5.88,
    '</tool_response>': 7.78,
    '<think>': 6.50,
    '</think>': 4.79,
}
ROLES = {'user': 5.26, 'assistant': 6.69, 'system': 8.11}

# Later markup: baseline, pulse size, age offset, decay exponent.
MARKUP_PULSES = {
    '<|im_start|>': (-0.19, 7.57, 4, 1),
    '<|endoftext|>': (0.004, 0.26, 1, 0.5),
    '<tool_call>': (-0.18, 2.83, 1, 1),
    '</tool_call>': (-0.12, 7.05, 1, 1),
    '<tool_response>': (0.02, 3.70, 2, 0.75),
    '</tool_response>': (-0.24, 43.08, 1, 1.5),
    '<think>': (-0.39, 2.83, 1, 0.75),
    '</think>': (-0.44, 0.75, 1, 0.5),
}
PUNCTUATION = {
    '#': -0.54, '##': -0.25, '.': -0.37, ',': -0.29, '_': 0.50,
    '/': 0.17, '\\': 0.17, '-': 0.10, ')': 0.07, ']': 0.07, '}': 0.07,
}


def opening(s):
    t = s.strip()
    if not t:
        return 0.40 if '\n' not in s else -0.10
    if all(unicodedata.category(c).startswith('P') for c in t):
        return -0.15 if '\n' in s else PUNCTUATION.get(t, -0.15)
    if t.isdigit():
        return 0.65 if t == '2' else 0.23
    if t in DECLARATIONS:
        return 0.22 if s.startswith(' ') else -0.11
    if t.startswith('#'):
        return -0.09
    if t.lower() in FUNCTION_WORDS:
        return -0.03 if s.startswith(' ') else 0.18
    value = 0.14 + 0.136 * min(len(t), 12) - 0.277 * s.startswith(' ')
    if t.istitle():
        value -= 0.13
    elif t.isupper():
        value += 0.29
    if any('\u3400' <= c <= '\u9fff' for c in t):
        value += 0.27
    return value


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        _, age, previous = carry
        age += 1
    value = 0.0
    if age == 0:
        value = OPENING_MARKERS[s] if s in OPENING_MARKERS else opening(s)
    elif previous == '<|im_start|>' and s in ROLES:
        exponent = 2 if s == 'assistant' else 1
        value = ROLES[s] * (2 / (age + 1)) ** exponent
    elif s == '<|im_end|>':
        if previous in {'</tool_call>', '</tool_response>'}:
            value = 0.16 + 87.15 / (age + 6) ** 1.5
        else:
            value = -0.38 + 46.63 / (age + 11) ** 1.5
    elif s in MARKUP_PULSES:
        base, size, offset, exponent = MARKUP_PULSES[s]
        value = base + size / (age + offset) ** exponent
    elif age < 8:
        value = 0.18 * opening(s) / age ** 1.8 + 0.016 / age ** 2
    return (doc, age, s), float(value)

