programs.sol:
"""A lexical detector for OK, not a general detector of agreement.

Predict a large negative response to OK/okay; joined-on lowercase 'ok' is
weaker than a separate word. Give smaller negative responses to short spelling
neighbours, Cyrillic ок, selected approval words, and forms of 'cook'. Case and
leading whitespace adjust the strength. Unmatched tokens get zero. Only the
previous character is remembered, and document boundaries reset that memory.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    bare = token.strip()
    spelling = bare.strip('._-()[]')
    word = spelling.lower()
    spaced = token[:1].isspace()

    value = 0.0
    if word == 'ok':
        if spelling.isupper():
            value = -5.15 if spaced else -5.6
        elif spelling[:1].isupper():
            value = -5.8
        elif spaced:
            value = -6.7
        elif bare != spelling:
            value = -5.8
        elif previous.isalpha():
            value = -4.9
        else:
            value = -6.6
    elif word == 'okay':
        value = -4.85 if spelling.islower() else -4.7
    elif word == 'ок':  # Cyrillic spelling, also used within Russian words.
        value = -3.6 if spaced else -2.05
    elif word == 'alright':
        value = -2.65 if spelling.islower() else -2.1
    elif word == 'fine':
        value = -1.8 if spaced and spelling.islower() else -1.2
    elif word in {'acceptable', 'satisfactory'}:
        value = -0.8
    elif word == 'yes':
        value = -0.55 if spelling[:1].isupper() else -0.4
    elif len(word) == 3 and word.endswith('ok'):
        if word[0] == 'o':
            value = -0.25 if spaced else -1.15
        elif word[0] in 'lrn':
            value = -1.75
        else:
            value = -2.8 if spelling.islower() else -3.5
    elif word.startswith('ok') and len(word) <= 5:
        if len(word) == 3:
            value = -3.45 if word[-1] == 'u' else -1.9
        else:
            value = -1.1
    elif len(word) == 3 and 'ок' in word:
        value = -2.3 if spaced else -1.2
    elif word in {'cook', 'cooking', 'cooked', 'cooker', 'cooks'}:
        if word == 'cook':
            value = -2.0 if spaced and spelling.islower() else -1.65
        else:
            value = -1.2
    elif word in {'uk', 'ox'}:
        value = -0.65

    return (doc, token[-1:]), value

programs.haiku:
"""Layer-0 MLP down-projection component 2103: an "OK" detector.

The component's activation goes strongly negative when the current token is the word
"ok" in any case ("ok", " OK", "Ok", "okay", " Okay"). It goes moderately negative on
the Cyrillic spelling "ок" (Russian for "ok"), on near-synonyms of "ok" ("fine",
"alright"), on words that look like "ok" (cook, cooking, cooked, cooker), and weakly on
other short tokens that carry an "ok" syllable ("Tok", "oku", "kok", "oker"). Everywhere
else it is 0, so the component is almost silent on ordinary text.

Each prediction depends only on the current token, so no carry is needed.
"""

import re

READS = ()

OK_WORDS = {"ok", "okay"}
CYRILLIC_OK = "ок"
NEAR_OK = {"fine", "alright"}
LOOKS_LIKE_OK = {"cook", "cooking", "cooked", "cooker"}
OK_SYLLABLE = re.compile(r"[^\W\d_]?ok[a-z]?")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in OK_WORDS:
        value = -5.5
    elif word == CYRILLIC_OK:
        value = -2.2
    elif word in NEAR_OK or word in LOOKS_LIKE_OK:
        value = -1.3
    elif OK_SYLLABLE.fullmatch(word):
        value = -2.0
    else:
        value = 0.0
    return carry, value

