programs.sol:
"""Predict the largest observed letter and mathematical-phrase responses.

A-breve is strongly negative, as are 'perfect square', 'absolute value', and
real-valued expressions. 'Common ancestor' is positive. Romanian diacritics
have smaller negative responses. Completing split Tamil consonants or Korean
beu syllables can be positive. Other tokens are zero. State resets by document.
"""
READS = ()

# Tamil consonants pa, ta, ka and na.
TAMIL_CONSONANTS = {
    'ப': 1.8,
    'த': 0.9,
    'க': 0.4,
    'ந': 0.55,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    prev, before = carry[1:] if same_doc else ('', '')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if token == 'ă':
        value = -1.16
    elif token == 'Ă':
        value = -0.88
    elif word == 'că':
        value = -0.43
    elif 'ă' in word:
        value = -0.26
    elif token in ('ț', 'ţ'):
        value = -0.21
    elif token in ('ș', 'ş', 'â'):
        value = -0.16
    elif word == 'în':
        value = -0.10
    elif word in ('square', 'squares'):
        value = -0.52 if prev == 'perfect' else -0.09
        if prev == 'prime':
            value = -0.30
    elif word in ('value', 'values'):
        value = -0.55 if prev == 'absolute' else -0.04
    elif word in ('ancestor', 'ancestors'):
        value = 0.06
        if prev == 'common':
            value = 0.52 if word == 'ancestor' else 0.26
    elif word == '-val':
        value = -0.40 if prev == 'real' else -0.12
    elif word == 'ued' and prev in ('-val', 'val'):
        value = -0.24 if before == 'real' else -0.12

    # Read combined decoding only to recognize a completed multibyte character.
    if '\ufffd' in token and same_doc:
        char = prefix.text_prefixes[-1][-1:]
        if char in TAMIL_CONSONANTS:
            value = TAMIL_CONSONANTS[char]
        elif char and 0x0B80 <= ord(char) <= 0x0BFF:
            value = 0.20
        elif char in ('브', '블'):  # Korean beu / beul
            value = 1.15 if char == '브' else 0.57
        elif char in ('≪', '≦'):
            value = 0.25
    return (doc, word, prev), float(value)

