    'completing': 7.6, 'completion': 6.6, 'completions': 5.0,
    'completely': 5.5, 'completeness': 3.9, 'incomplete': 5.9,
    'incompletely': 3.8, 'complet': 6.1, 'autocomplete': 3.4,
