    '完': 6.4, '完成': 6.1, '完全': 3.9, '完整': 5.4,
    '完整的': 5.0, '完了': 4.4, '完毕': 4.4, '完善': 2.3,
    '完工': 2.9, '完备': 3.5, '完结': 2.5, '完美': 1.25,
    '全': 1.0, '成': 0.95, '成功': 0.7,
}
RELATED = (
    (4.3, {'полностью', 'complète'}),
    (3.2, {'entirely', 'zupełnie'}),
    (2.5, {'completamente', 'völlig'}),
    (1.5, {'fully', 'totally', 'accomplish'}),
    (1.2, {'full', 'entire', 'done', 'accomplished', 'wholly'}),
    (0.9, {'sufficient', 'adequate', 'ready', 'missing', 'intact'}),
    (0.75, {'successful', 'successfully', 'finally', 'thoroughly',
            'sufficiently', 'comprehensive', 'altogether'}),
    (0.5, {'enough', 'achieve', 'achieved', 'solve', 'solved',
           'succeed', 'perfect', 'perfectly', 'correct'}),
)
