    elif word in FINISH:
        value = FINISH[word]
        if token[:1].isupper() or not boundary:
            value *= 0.75
    elif word.startswith('compet'):
        value = 2.0 if word in {'compete', 'competed'} else 1.5
    else:
        for strength, words in RELATED:
            if word in words:
                value = strength
                break
