        value = 0.25  # Usually a suffix, not the separate word.
    if token == '</think>':
        value = 0.74
    if token == 'Comple':
        value = 4.9
    if 'Complete' in token and word not in COMPLETE and token != 'Comple':
        value = 4.5  # Completion callbacks in code identifiers.
    if not boundary and tail.endswith(('com', 'kom')) and token in ENDINGS:
        value = ENDINGS[token] * (0.65 if tail.endswith('incom') else 1.0)
    elif not boundary and tail.endswith(('comple', 'complet')):
        value = {'ting': 7.2, 'ions': 4.6, 'teness': 2.7,
                 'tes': 3.7}.get(token, value)
    elif not boundary and token in {'ple', 'plet'}:
        value = 1.25 if token == 'ple' else 1.5
    if word == 'of' and previous == 'completion':
        value = 4.0
    if word in {'the', 'a', 'an'}:
        echo = {'complete': 2.7, 'completed': 1.1,
                'completing': 1.6, 'completes': 1.6}.get(previous, 0.0)
        value = max(value, echo * (1.0 if word == 'the' else 0.5))
    match = re.search(r'[A-Za-z]+$', tail + raw)
    tail = match.group().lower()[-20:] if match else ''
    return (doc, word, tail), float(value)

