"""Completion words. The component fires on the current token when it names something being
complete, finished, entire or full (complete > finish > entire/full/done > adequate/enough).
Other tokens give 0. Activation is a hand-set strength per word class."""
READS = ()

def step(carry, prefix, upstream):
    t = prefix.token_strings[-1].strip().lower()
    if "complet" in t or "complèt" in t or "完成" in t or "完整" in t or "完全" in t or "完了" in t:
        value = 6.5            # complete, completed, completion, completely, incomplete, 完成
    elif "完" in t:
        value = 4.0            # other Chinese 完 (finish): 完工, 完毕, 看完
    elif t.startswith("полност"):
        value = 4.0            # Russian "fully"
    elif t.startswith("plet") or t.startswith("deplet"):
        value = 3.0            # the "-plete" fragment: pletion, pleted, plete, depletion
    elif t.startswith("finish") or t.startswith("unfinish"):
        value = 3.0            # finish, finished, finishes
    elif t.startswith("entirely"):
        value = 3.2
    elif t.startswith(("entire", "full", "fully", "done", "totally", "accomplish", "compet", "exhaust")):
        value = 1.4            # entire, full, fully, done, accomplish, compete, competition
    elif t.startswith(("sufficien", "thorough", "comprehensive", "enough", "correct", "ready",
                       "adequate", "missing", "successful", "finally", "achieve")):
        value = 0.7            # enough, sufficient, ready, adequate, missing, successful
    elif t == "</think>" or t == "</think":
        value = 0.7            # end of a reasoning block: "finished thinking"
    else:
        value = 0.0
    return carry, float(value)

