import math

READS = ()
OUTPUT = set('console Console logger log printf fprintf cout fmt System'.split())

WORDS = {
    'await': (1.71, 0.89, 2.17),
    'break': (-0.05, 0.52, 1.50),
    'case': (-0.05, 0.07, 0.76),
    'catch': (-0.06, -0.16, 0.04),
    'const': (-0.09, 0.07, 0.74),
    'continue': (0.01, 0.43, 2.04),
    'do': (-0.06, -0.01, 0.36),
    'elif': (0.42, 0.71, 1.72),
    'else': (0.25, 0.28, 1.00),
    'except': (-0.16, -0.05, 0.55),
    'finally': (0.06, 0.27, 0.53),
    'for': (-0.01, 0.13, 1.88),
    'foreach': (0.28, 0.39, 1.55),
    'if': (-0.08, 0.10, 3.00),
    'let': (-0.00, 0.06, 1.05),
    'new': (-0.07, 0.04, 0.57),
    'print': (-0.21, -0.09, 0.41),
    'return': (0.21, 0.34, 1.30),
    'self': (0.34, 0.49, 1.20),
    'super': (0.00, 0.23, 1.61),
    'switch': (-0.08, 0.18, 1.32),
    'this': (0.02, 0.54, 1.39),
    'throw': (-0.12, 0.10, 0.34),
    'try': (0.02, 0.16, 2.17),
    'var': (-0.16, 0.02, 0.57),
    'while': (-0.07, 0.09, 1.43),
    'yield': (-0.00, 0.16, 1.34),
}

GROUPS = {
    'assertion': (0.30, 0.42, 1.38),
    'assertion-method': (0.45, 1.21, 1.46),
    'equality-test-method': (0.00, 1.92, 0.00),
    'assertion-function-suffix': (0.00, 0.57, 0.00),
    'assertion-macro-suffix': (0.00, 1.95, 0.00),
    'expectation': (0.07, 0.15, 0.69),
    'output': (0.06, 0.06, 0.65),
    'closing-brace': (-0.04, -0.03, 0.52),
    'closing-brace-line': (0.05, 0.06, 0.61),
    'opening-parenthesis': (0.00, 0.12, 0.20),
    'double-parenthesis': (0.14, 0.19, 0.45),
    'negated-parenthesis': (1.16, 0.63, 0.45),
    'hash-comment': (-0.12, -0.01, 0.29),
    'line-comment': (-0.04, 0.05, 0.26),
    'dollar': (0.01, -0.01, 0.75),
    'reference': (0.20, 0.28, 0.38),
    'shift': (-0.19, -0.09, -0.25),
    'identifier': (0.00, 0.00, 0.04),
}


def lexical_group(word, token):
    assertion = word.lstrip('.')
    if assertion == 'assertEqual':
        return 'equality-test-method'
    if (assertion.startswith('assert') and len(assertion) > 6
            and assertion[6].isupper()):
        return 'assertion-method'
    if assertion in {'assert', 'Assert', 'ASSERT'}:
        return 'assertion'
    if word in {'_eq', '_EQ'}:
        return ('assertion-function-suffix' if word == '_eq'
                else 'assertion-macro-suffix')
    if word in {'expect', 'EXPECT'}:
        return 'expectation'
    if word in OUTPUT:
        return 'output'
    if word == '}':
        return 'closing-brace-line' if '\n' in token else 'closing-brace'
    punctuation = {'(': 'opening-parenthesis', '((': 'double-parenthesis',
                   '$': 'dollar', '&': 'reference', '(&': 'reference',
                   '<<': 'shift', '>>': 'shift'}
    if word in punctuation:
        return punctuation[word]
    if word.startswith(('(!', '!(')):
        return 'negated-parenthesis'
    if word.startswith('//'):
        return 'line-comment'
    if word.startswith('#'):
        return 'hash-comment'
    return 'identifier' if word.isidentifier() else None


def construction(word, token, previous):
    prev = previous.strip()
    if word in {'not', '!'} and prev in {'if', 'elif', 'while', '&&', '||'}:
        return 0.57
    if word == 'param' and prev.endswith('@'):
        return 0.70
    if token.startswith('\t') or (previous and all(c in ' \t' for c in previous)):
        return None
    if word == 'if' and prev == 'else':
        return 2.09
    if word in {'(', '(('}:
        if prev == 'if':
            return 0.83
        if prev in {'for', 'foreach', 'while', 'switch'}:
            return 0.42
    if word in {'new', 'this', 'self', '$', 'super'}:
        if prev in {'=', ':=', '=>', '+=', '-='}:
            return {'new': 0.51, 'this': 1.01, 'self': 0.86,
                    '$': 0.45, 'super': 0.92}[word]
        if prev in {'return', 'throw', 'await'}:
            return {'new': 0.54, 'this': 1.25, 'self': 1.12,
                    '$': 0.56, 'super': 1.24}[word]
        if word == 'self' and prev in {'if', 'elif', 'while', 'not'}:
            return 0.73
        if word == 'this' and prev.endswith('$'):
            return 1.01
    if word in {'if', 'for', 'while', 'try'} and not token.startswith(' '):
        if '\n' in previous or previous.endswith(('\\n', '\\t')):
            return {'if': 0.66, 'for': 0.42, 'while': 0.37, 'try': 0.52}[word]
    return None


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    word = token.strip()
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    state = (doc, token)
    indented = bool(previous) and all(c in ' \t' for c in previous)

    if fresh:
        if token == '\t':
            return state, 1.09
        if word in {'if', 'try', '('}:
            return state, {'if': 1.0, 'try': 0.88, '(': 0.73}[word]
        if word.startswith('<') and word.endswith('>') and len(word) > 4:
            return state, 0.19
    if not word:
        if fresh and ('\n' in token or '\r' in token):
            return state, -0.11
        if token == '\t':
            return state, 0.69 if indented else 0.09 if '\n' in previous else -0.09
        if '\n' in token or '\r' in token:
            return state, 0.0
        return state, ((0.28 if indented else -0.02)
                       if '\t' in token else -0.01)

    value = construction(word, token, previous)
    if value is not None:
        return state, value
    ordinary, bare, statement = WORDS.get(
        word, GROUPS.get(lexical_group(word, token), (0.0, 0.0, 0.0)))
    if token.startswith('\t'):
        strength, offset = (1.1, 0.35) if indented else (0.7, 0.1)
        if word == 'return':
            offset -= 0.35
    elif indented and (token.startswith(' ') or word == '}'):
        width = math.log2(1 + len(previous)) - 3 if token.startswith(' ') else 0
        strength = 0.7 if '\t' in previous else 1.0 + 0.1 * width
        offset = 0.0
    else:
        return state, ordinary if token.startswith(' ') else bare
    return state, float(ordinary + strength * (statement - ordinary) + offset)

