STATEMENTS = {
    'if': 2.6, 'for': 2.1, 'try': 2.2, 'return': 1.0,
    'break': 1.7, 'else': 1.2, 'except': 0.8, 'assert': 1.2,
    'assertthat': 1.4, 'while': 1.1, 'case': 0.8, 'switch': 0.8,
    'do': 0.5, 'yield': 0.7, 'throw': 0.6, 'catch': 0.7,
    'finally': 0.6,
}

IDENTIFIERS = {
    'self': 0.8, 'this': 0.8, 'let': 0.7, 'const': 0.7,
    'new': 0.5, 'int': 0.6, 'string': 0.6, 'console': 0.7,
    'logger': 0.7, 'cout': 0.45, 'param': 0.6,
    'isinstance': 0.7, 'std': 0.3, 'math': 0.4,
    'cursor': 0.4, 'public': 0.2, 'private': 0.2,
