def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history = ''
    else:
        history = carry[1]

    word = token.strip().lower()
    value = STATEMENTS.get(word, IDENTIFIERS.get(word, 0.0))
    if value:
        code_marks = ('{', '}', ';', '->', '::', '=>', '\t', 'def ', 'class ')
        in_code = any(mark in history for mark in code_marks)
        # Words with a leading blank are common statement tokens. Unmarked words
        # need stronger evidence from nearby source punctuation.
        if in_code:
