"""Comma detector: a comma that closes a clause of running prose pushes the component negative.

The component is a comma-responder. Off a comma it is about zero. On a comma it goes
negative, and how negative depends on what the comma follows:
  - a word (letters, including CJK and Cyrillic), after a stretch of words in the same
    sentence: the longer the sentence has run (counted in words since the last sentence
    end), the more negative, reaching about -0.85 after roughly 10 words. A comma right
    after a sentence start (a word or two in) is weak;
  - a digit (as in 1,000 or a list of numbers): weak;
  - a bracket, quote or other symbol before it: moderate;
  - a comma on its own line: zero.
"""

READS = ()

COMMA_MARKS = {",", "，", "、", "،"}
SENTENCE_END = (".", "!", "?", "\n", "。")


def words_strength(words):
    if words < 2:
        return -0.15
    if words < 4:
        return -0.3
    if words < 6:
        return -0.45
    if words < 8:
        return -0.65
    if words < 10:
        return -0.75
    return -0.85


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    words = 0 if (carry is None or new_doc) else carry
    if any(ch in tok for ch in SENTENCE_END):
        new_carry = 0
    elif tok.strip().isalpha():
        new_carry = words + 1
    else:
        new_carry = words
    if not any(ch in tok for ch in COMMA_MARKS) or "\n" in tok:
        return new_carry, 0.0
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if prev[-1:].isdigit():
        return new_carry, -0.15
    if prev[-1:].isalpha():
        return new_carry, words_strength(words)
    return new_carry, -0.4

