"""Predict the component's comma pulse from punctuation shape and nearby word class."""

READS = ()
COMMAS = (",", "，", "、")


def previous_word_response(prefix):
    previous = ""
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    last = next((char for char in reversed(previous) if not char.isspace()), "")
    if last.isalpha():
        return -0.72 if any(char.isspace() for char in previous) else -0.50
    if last.isdigit():
        return -0.16
    return -0.18 if last else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not any(mark in token for mark in COMMAS):
        return None, 0.0
    if "\n" in token or "\r" in token:
        return None, 0.0
    if token == "，":
        return None, -0.70
    if token == "、":
        return None, -0.43

    comma_at = min(token.find(mark) for mark in COMMAS if mark in token)
    if comma_at and token[comma_at - 1] in "\"'“”‘’":
        return None, -0.18
    if token.startswith(",") and len(token) > 1 and token[1].isascii() and token[1].isalnum():
        return None, -0.68
    if any(char.isspace() for char in token):
        return None, -0.30 if token.strip() == "," else 0.0
    if any(char.isalpha() or char.isdigit() for char in token):
        return None, -0.18
    if comma_at + 1 < len(token) and token[comma_at + 1] in "\"'":
        return None, 0.5 * previous_word_response(prefix)
    return None, previous_word_response(prefix)

