    if token == "'" and previous in ELIDED_WORDS:
        return 0.0
    if token == '#' and previous.strip() == 'C':
        return -4.2
    strength = STRENGTH.get(token)
    if strength is not None:
        if spaced:
            if token == '\\':
                return 0.3
            return 0.15 if token in {'*', '**'} else 0.0
        scale = 1.0 if letter else 0.65 if digit else 0.15
        if letter and token != "'":
            length = len(previous.strip(' ./_-'))
            scale *= 0.78 if length == 1 else 0.97 if length < 4 else 1.08
            if token == '\\' and length >= 7:
                scale *= 1.4
        if digit and token == '/':
            scale = 0.36
        elif digit and token in {'%', '\\', '$', '[]'}:
            scale = 0.9
        if token == '\\' and not (letter or digit):
            return -0.45
        return -strength * scale

    # Joined forms of familiar operators and punctuation.
    if token.startswith(' ') and token.strip() in {'--', '<<', '__', '``', '...'}:
        return -0.5 if token.strip() == '<<' else -0.3
    if (token.startswith('#') and token[1:2].isalpha()
            and previous[-1:].isalnum()):
        return -2.6
    if token == '&#':
        return -1.4 if letter or digit else -0.3
    if token[:1] in {'\"', "'"} and token[1:] in {',', ':', ';', '.'}:
        return -0.2 if letter or digit else 0.0
    if token == '$$':
        return -0.6 if letter or digit else 0.0
    if token.startswith('__') and token[2:] in {'/', '.', '-'}:
        return -2.5 if letter or digit else -0.3
    if token.startswith('\\x') and all(c in 'abcdef0123456789x' for c in token[1:]):
        if token == '\\x' and digit:
            return -1.5
        return -0.8 if len(token) > 2 else -0.9
    if (token.startswith('\\') and len(token) > 1
            and all(c in '\\"\'$,:' for c in token)):
        if spaced:
            return 0.0
        if token.endswith((',', ':', ';', ')')):
            return -0.75 if letter or digit else -0.3
        return -1.35 if letter or digit else -0.4
    if token.startswith('%') and all(not c.isalnum() for c in token[1:]):
        return -0.95 if letter or digit else -0.2
    if token.startswith('()') and all(not c.isalnum() for c in token[2:]):
        if any(c.isspace() or c == ';' for c in token[2:]):
            return -0.15 if letter or digit else 0.0
        return -0.65 if letter or digit else -0.1
    if (not token[0:1].isspace() and token.endswith('\\')
            and all(c in ')]}\'"' for c in token[:-1])):
        return -0.4
    if token in {'–', '‐', '−'}:
        return -1.0 if letter else -0.65 if digit else -0.15
    if token in {'—', ' —', '…', ' ...'}:
        return -0.3
    if token == '’':
        return -0.18
    if token in {'“', '”', 'ʼ'}:
        return -0.4 if letter else -0.25 if digit else 0.0
    if token in {'©', '®', '™'}:
        return -0.9 if letter else -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if token in {"'s", '’s'}:
        base = previous.strip().lower()
        if base in CONTRACTION_BASES:
            value = 0.07
        else:
            value = -0.13 if base == 'what' else -0.8
    elif token in GENITIVE_MARKERS:
        value = GENITIVE_MARKERS[token]
    elif token == '\x00':
        value = -0.65
    elif token == '\xa0':
        value = -0.3
    else:
        value = punctuation_value(token, previous)
    return (doc, token), float(value)

