"""layers.0.mlp.down_proj:2110: a "glued symbol" detector.

What it does: this component goes negative on a punctuation or symbol token that is
stuck directly onto the end of a word, with no space in between. That is typical of
code, file paths, identifiers and namespaces: "reagento__dishka", "node_modules/x",
"App\\Domain", "user@host", "C#", "50%", "--flag". Possessive markers stuck to a word
("Martha's", "Martha’s", and the Chinese/Japanese genitive particles 的 and の, 의) are
negative too. Ordinary words and digits, symbols after a space, and clause punctuation
(. , : ; ) ] } ， 。 、 and newlines) stay at about zero.

How strong: "__", "@" and "#" are the strongest (about -3). "%", "\\", "$", "&", "--"
and hex escapes are about -1.4. "/", "-", "_", "::", quotes, backticks, "*", "+", "<", ">"
and "[" are about -0.8. Other glued symbols, such as "(" or "=", are about -0.2.
Possessive markers are about -0.5 ("'s") to -0.9 (的).

Only the previous token and the current one are read, so there is no carry.
"""

READS = ()

STRONG = {"__": 3.0, "@": 3.0, "#": 3.0, "__/": 2.5, "__.": 2.5}
MIDDLE = {"%": 1.4, "\\": 1.4, "\\\\": 1.9, "$": 1.4, "&": 1.4, "--": 1.3, "[]": 1.5,
          "\\x": 1.4, "&#": 1.4}
WEAK = {s: 0.8 for s in ["/", "-", "_", "::", "`", "*", "**", "+", "!", ">", "<", "[",
                         "..", "...", '"', "'", "->", "^", "–", "|"]}
CLOSERS = {".", ",", ":", ";", ")", "]", "}", "?", "\n", "，", "。", "、", "）", "」"}
OTHER = 0.2
POSSESSIVE = {"'s": 0.5, "’s": 0.5, "的": 0.9, "の": 0.7, "의": 0.7}


def is_symbol(s):
    """True if the token is made only of characters that are neither letters, digits nor spaces."""
    return len(s) > 0 and all(not c.isalnum() and not c.isspace() for c in s)


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, 0.0
    if not prefix.token_strings[t - 1][-1:].isalnum():
        return carry, 0.0  # the token follows a space or a symbol, not a word
    if token in POSSESSIVE:
        strength = POSSESSIVE[token]
    elif not is_symbol(token) or token in CLOSERS:
        strength = 0.0
    elif token in STRONG:
        strength = STRONG[token]
    elif token in MIDDLE:
        strength = MIDDLE[token]
    elif token in WEAK:
        strength = WEAK[token]
    else:
        strength = OTHER
    return carry, -strength

