"""A small negative cue for non-routine punctuation after a word or number."""
import unicodedata
READS = ()

PLAIN_SENTENCE_MARKS = set('.,;:!?')

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if not token or token in PLAIN_SENTENCE_MARKS:
        return None, -0.0251
    if unicodedata.category(token[0])[0] not in 'PS':
        return None, -0.0251
    if len(prefix.token_strings) < 2:
        return None, -0.0251
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.0251
    previous = prefix.token_strings[-2].rstrip()
    if previous and (previous[-1].isalnum() or previous[-1] == '_'):
        return None, -0.1
    return None, -0.0251

"""Estimate a positive response for long word pieces and stronger chat-turn markers."""
READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    if text.startswith(("<|im_", "<tool_", "</tool_")):
        return None, 2.0

    n = len(text)
    if n <= 3:
        value = 0.0
    elif n <= 5:
        value = 0.03
    elif n <= 7:
        value = 0.10
    else:
        value = 0.16
    return None, float(value)
